insert into public.questoes (numero, parte, capitulo, pergunta, resposta, status)
values
  (421, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Como se explica que duas pessoas, perfeitamente acordadas, tenham instantaneamente a mesma idéia?', 'São dois Espíritos simpáticos que se comunicam e vêem reciprocamente seus pensamentos respectivos, embora sem estarem adormecidos os corpos." Há, entre os Espíritos que se encontram, uma comunicação de pensamento, que dá causa a que duas pessoas se vejam e compreendam sem precisarem dos sinais ostensivos da linguagem. Poder-se-ia dizer que falam entre si a linguagem dos Espíritos.', 'rascunho'),
  (422, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Os letárgicos e os catalépticos, em geral, vêem e ouvem o que em derredor se diz e faz, sem que possam exprimir que estão vendo e ouvindo. É pelos olhos e pelos ouvidos que têm essas percepções?', 'Não; pelo Espírito. O Espírito tem consciência de si, mas não pode comunicar-se." a) — Por quê? "Porque a isso se opõe o estado do corpo. E esse estado especial dos órgãos vos prova que no homem há alguma coisa mais do que o corpo, pois que, então, o corpo já não funciona e, no entanto, o Espírito se mostra ativo.', 'rascunho'),
  (423, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Na letargia, pode o Espírito separar-se inteiramente do corpo, de modo a imprimir-lhe todas as aparências da morte e voltar depois a habitá-lo?', 'Na letargia, o corpo não está morto, porquanto há funções que continuam a executar-se. Sua vitalidade se encontra em estado latente, como na crisálida, porém não aniquilada. Ora, enquanto o corpo vive, o Espírito se lhe acha ligado. Em se rompendo, por efeito da morte real e pela desagregação dos órgãos, os laços que prendem um ao outro, integral se torna a separação e o Espírito não volta mais ao seu envoltório. Desde que um homem, aparentemente morto, volve à vida, é que não era completa a morte.', 'rascunho'),
  (424, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Por meio de cuidados dispensados a tempo, podem reatar-se laços prestes a se desfazerem e restituir-se à vida um ser que definitivamente morreria se não fosse socorrido?', 'Sem dúvida e todos os dias tendes a prova disso. O magnetismo, em tais casos, constitui, muitas vezes, poderoso meio de ação, porque restitui ao corpo o fluido vital que lhe falta para manter o funcionamento dos órgãos." A letargia e a catalepsia derivam do mesmo princípio, que é a perda temporária da sensibilidade e do movimento, por uma causa fisiológica ainda inexplicada. Diferem uma da outra em que, na letargia, a suspensão das forças vitais é geral e dá ao corpo todas as aparências da morte; na catalepsia, fica localizada, podendo atingir uma parte mais ou menos extensa do corpo, de sorte a permitir que a inteligência se manifeste livremente, o que a torna inconfundível com a morte. A letargia é sempre natural; a catalepsia é por vezes magnética.', 'rascunho'),
  (425, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'O sonambulismo natural tem alguma relação com os sonhos? Como explicá- lo?', 'É um estado de independência do Espírito, mais completo do que no sonho, estado em que maior amplitude adquirem suas faculdades. A alma tem então percepções de que não dispõe no sonho, que é um estado de sonambulismo imperfeito." 160 – Allan Kar dec "No sonambulismo, o Espírito está na posse plena de si mesmo. Os órgãos materiais, achando-se de certa forma em estado de catalepsia, deixam de receber as impressões exteriores. Esse estado se apresenta principalmente durante o sono, ocasião em que o Espírito pode abandonar provisoriamente o corpo, por se encontrar este gozando do repouso indispensável à matéria. Quando se produzem os fatos do sonambulismo, é que o Espírito, preocupado com uma coisa ou outra, se aplica a uma ação qualquer, para cuja prática necessita de utilizar-se do corpo. Serve-se então deste, como se serve de uma mesa ou de outro objeto material no fenômeno das manifestações físicas, ou mesmo como se utiliza da mão do médium nas comunicações escritas. Nos sonhos de que se tem consciência, os órgãos, inclusive os da memória, começam a despertar. Recebem imperfeitamente as impressões produzidas por objetos ou causas externas e as comunicam ao Espírito, que, então, também em repouso, só experimenta, do que lhe é transmitido, sensações confusas e, amiúde, desordenadas, sem nenhuma aparente razão de ser, mescladas que se apresentam de vagas recordações, quer da existência atual, quer de anteriores. Facilmente, portanto, se compreende por que os sonâmbulos nenhuma lembrança guardam do que se passou enquanto estiveram no estado sonambúlico e por que os sonhos, de que se conserva memória, as mais das vezes não têm sentido. Digo — as mais das vezes, porque também sucede serem a conseqüência de lembrança exata de acontecimentos de uma vida anterior e até, não raro, uma espécie de intuição do futuro.', 'rascunho'),
  (426, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'O chamado sonambulismo magnético tem alguma relação com o sonambulismo natural?', 'É a mesma coisa, com a só diferença de ser provocado.', 'rascunho'),
  (427, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'De que natureza é o agente que se chama fluido magnético?', 'Fluido vital, eletricidade animalizada, que são modificações do fluido universal.', 'rascunho'),
  (428, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Qual a causa da clarividência sonambúlica?', 'Já o dissemos: É a alma que vê.', 'rascunho'),
  (429, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Como pode o sonâmbulo ver através dos corpos opacos?', 'Não há corpos opacos senão para os vossos grosseiros órgãos. Já precedentemente não dissemos que a matéria nenhum obstáculo oferece ao Espírito, que livremente a atravessa? Freqüentemente ouvis o sonâmbulo dizer que vê pela fronte, pelo punho, etc., porque, achando-vos inteiramente presos à matéria, não compreendeis lhe seja possível ver sem o auxílio dos órgãos. Ele próprio, pelo desejo que manifestais, julga precisar dos órgãos. Se, porém, o deixásseis livre, compreenderia que vê por todas as partes do seu corpo, ou, melhor falando, que vê de fora do seu corpo.', 'rascunho'),
  (430, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Pois que a sua clarividência é a de sua alma ou de seu Espírito, por que é que o sonâmbulo não vê tudo e tantas vezes se engana?', 'Primeiramente, aos Espíritos imperfeitos não é dado verem tudo e tudo saberem. Não ignoras que ainda partilham dos vossos erros e prejuízos. Depois, quando unidos à matéria, não gozam de todas as suas faculdades de Espírito. Deus outorgou ao homem a faculdade sonambúlica para fim útil e sério, não para que se informe do que não deva saber. Eis por que os sonâmbulos nem tudo podem dizer.', 'rascunho'),
  (431, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Qual a origem das idéias inatas do sonâmbulo e como pode falar com exatidão de coisas que ignora quando desperto, de coisas que estão mesmo acima de sua capacidade intelectual?', 'É que o sonâmbulo possui mais conhecimentos do que os que lhe supões. Apenas, tais conhecimentos dormitam, porque, por demasiado imperfeito, seu invólucro corporal não lhe consente rememorá-lo. Que é, afinal, um sonâmbulo? Espírito, como nós, e que se encontra encarnado na matéria para cumprir a sua missão, despertando dessa letargia quando cai em estado sonambúlico. Já te temos dito, repetidamente, que vivemos muitas vezes. Esta mudança é que, ao sonâmbulo, como a qualquer Espírito ocasiona a perda material do que haja aprendido em precedente existência. Entrando no estado, a que chamas crise, lembra-se do que sabe, mas sempre de modo incompleto. Sabe, mas não poderia dizer donde lhe vem o que sabe, nem como possui os conhecimentos que revela. Passada a crise, toda recordação se apaga e ele volve à obscuridade." Mostra a experiência que os sonâmbulos também recebem comunicações de outros Espíritos, que lhes transmitem o que devam dizer e suprem à incapacidade que denotam. Isto se verifica principalmente nas prescrições médicas. O Espírito do sonâmbulo vê o mal, outro lhe indica o remédio. Essa dupla ação é às vezes patente e se revela, além disso, por estas expressões muito freqüentes: dizem-me que diga, ou proíbem-me que diga tal coisa. Neste último caso, há sempre perigo em insistir-se por uma revelação negada, porque se dá azo a que intervenham Espíritos levianos, que falam de tudo sem escrúpulo e sem se importarem com a verdade.', 'rascunho'),
  (432, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Como se explica a visão a distância em certos sonâmbulos?', 'Durante o sono, a alma não se transporta? O mesmo se dá no sonambulismo.', 'rascunho'),
  (433, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'O desenvolvimento maior ou menor da clarividência sonambúlica depende da organização física, ou só da natureza do Espírito encarnado?', 'De uma e outra. Há disposições físicas que permitem ao Espírito desprender-se mais ou menos facilmente da matéria.', 'rascunho'),
  (434, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'As faculdades de que goza o sonâmbulo são as que tem o Espírito depois da morte?', 'Somente até certo ponto, pois cumpre se atenda à influência da matéria a que ainda se acha ligado.', 'rascunho'),
  (435, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Pode o sonâmbulo ver os outros Espíritos? 162 – Allan Kar dec', 'A maioria deles os vê muito bem, dependendo do grau e da natureza da lucidez de cada um. É muito comum, porém, não perceberem, no primeiro momento, que estão vendo Espíritos e os tomarem por seres corpóreos. Isso acontece principalmente aos que, nada conhecendo do Espiritismo, ainda não compreendem a essência dos Espíritos. O fato os espanta e os faz supor que têm diante da vista seres terrenos." O mesmo se dá com os que, tendo morrido, ainda se julgam vivos. Nenhuma alteração notando ao seu derredor e parecendo-lhes que os Espíritos têm corpos iguais aos nossos, tomam por corpos reais os corpos aparentes com que os mesmos Espíritos se lhes apresentam.', 'rascunho'),
  (436, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'O sonâmbulo que vê, à distância, vê do ponto em que se acha o seu corpo, ou do em que está sua alma?', 'Por que esta pergunta, desde que sabes ser a alma quem vê e não o corpo?', 'rascunho'),
  (437, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Posto que o que se dá, nos fenômenos sonambúlicos, é que a alma se transporta, como pode o sonâmbulo experimentar no corpo as sensações do frio e do calor existentes no lugar onde se acha sua alma, muitas vezes bem distante do seu invólucro?', 'A alma, em tais casos, não tem deixado inteiramente o corpo; conserva-se- lhe presa pelo laço que os liga e que então desempenha o papel de condutor das sensações. Quando duas pessoas se comunicam de uma cidade para outra, por meio da eletricidade, esta constitui o laço que lhes liga os pensamentos. Daí vem que confabulam como se estivessem ao lado uma da outra.', 'rascunho'),
  (438, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'O uso que um sonâmbulo faz da sua faculdade influi no estado do seu Espírito depois da morte?', 'Muito, como o bom ou mau uso que o homem faz de todas as faculdades com que Deus o dotou.', 'rascunho'),
  (439, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Que diferença há entre o êxtase e o sonambulismo?', 'O êxtase é um sonambulismo mais apurado. A alma do extático ainda é mais independente.', 'rascunho'),
  (440, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'O Espírito do extático penetra realmente nos mundos superiores?', 'Vê esses mundos e compreende a felicidade dos que os habitam, donde lhe nasce o desejo de lá permanecer. Há, porém, mundos inacessíveis aos Espíritos que ainda não estão bastante purificados.', 'rascunho'),
  (441, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Quando o extático manifesta o desejo de deixar a Terra, fala sinceramente, não o retém o instinto de conservação?', 'Isso depende do grau de purificação do Espírito. Se verifica que a sua futura situação será melhor do que a sua vida presente, esforça-se por desatar os laços que o prendem à Terra.', 'rascunho'),
  (442, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Se se deixasse o extático entregue a si mesmo, poderia sua alma abandonar definitivamente o corpo?', 'Perfeitamente, poderia morrer. Por isso é que preciso se torna chamá-lo a voltar, apelando para tudo o que o prende a este mundo, fazendo-lhe sobretudo compreender que a maneira mais certa de não ficar lá, onde vê que seria feliz, consistiria em partir a cadeia que o tem preso ao planeta terreno.', 'rascunho'),
  (443, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Pretendendo que lhe é dado ver coisas que evidentemente são produto de uma imaginação que as crenças e prejuízos terrestres impressionaram, não será justo concluir-se que nem tudo o que o extático vê é real?', 'O que o extático vê é real para ele. Mas, como seu Espírito se conserva sempre debaixo da influência das idéias terrenas, pode acontecer que veja a seu modo, ou melhor, que exprima o que vê numa linguagem moldada pelos preconceitos e idéias de que se acha imbuído, ou, então, pelos vossos preconceitos e idéias, a fim de ser mais bem compreendido. Neste sentido, principalmente, é que lhe sucede errar.', 'rascunho'),
  (444, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Que confiança se pode depositar nas revelações dos extáticos?', 'O extático está sujeito a enganar-se muito freqüentemente, sobretudo quando pretende penetrar no que deva continuar a ser mistério para o homem, porque, então, se deixa levar pela corrente das suas próprias idéias, ou se torna joguete de Espíritos mistificadores, que se aproveitam da sua exaltação para fasciná- lo.', 'rascunho'),
  (445, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Que deduções se podem tirar dos fenômenos do sonambulismo e do êxtase? Não constituirão uma espécie de iniciação na vida futura?', 'A bem dizer, mediante esses fenômenos, o homem entrevê a vida passada e a vida futura. Estude-os e achará o aclaramento de mais de um mistério, que a sua razão inutilmente procura devassar.', 'rascunho'),
  (446, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Poderiam tais fenômenos adequar-se às idéias materialistas?', 'Aquele que os estudar de boa-fé e sem prevenções não poderá ser materialista, nem ateu.', 'rascunho'),
  (447, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'O fenômeno a que se dá a designação de dupla vista tem alguma relação com o sonho e o sonambulismo?', 'Tudo isso é uma só coisa. O que se chama dupla vista é ainda resultado da libertação do Espírito, sem que o corpo seja adormecido. A dupla vista ou segunda vista é a vista da alma." 164 – Allan Kar dec', 'rascunho'),
  (448, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'É permanente a segunda vista?', 'A faculdade é, o exercício não. Em os mundos menos materiais do que o vosso, os Espíritos se desprendem mais facilmente e se põem em comunicação apenas pelo pensamento, sem que, todavia, fique abolida a linguagem articulada. Por isso mesmo, em tais mundos, a dupla vista é faculdade permanente, para a maioria de seus habitantes, cujo estado normal se pode comparar ao dos vossos sonâmbulos lúcidos. Essa também a razão por que esses Espíritos se vos manifestam com maior facilidade do que os encarnados em corpos mais grosseiros.', 'rascunho'),
  (449, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'A segunda vista aparece espontaneamente ou por efeito da vontade de quem a possui como faculdade?', 'As mais das vezes é espontânea, porém a vontade também desempenha com grande freqüência importante papel no seu aparecimento. Toma, para exemplo, de umas dessas pessoas a quem se dá o nome de ledoras da buena--dicha, algumas das quais dispõem desta faculdade, e verás que é com o auxílio da própria vontade que se colocam no estado de terem a dupla vista e o que chamas visão.', 'rascunho'),
  (450, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'A dupla vista é suscetível de desenvolver-se pelo exercício?', 'Sim, do trabalho sempre resulta o progresso e a dissipação do véu que encobre as coisas." a) — Esta faculdade tem qualquer ligação com a organização física? "Incontestavelmente, o organismo influi para a sua existência. Há organismos que lhe são refratários.', 'rascunho'),
  (451, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Por que é que a segunda vista parece hereditária em algumas famílias?', 'Por semelhança da organização, que se transmite como as outras qualidades físicas. Depois, a faculdade se desenvolve por uma espécie de educação, que também se transmite de um a outro.', 'rascunho'),
  (452, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'É exato que certas circunstâncias desenvolvem a segunda vista?', 'A moléstia, a proximidade do perigo, uma grande comoção podem desenvolvê-la. O corpo, às vezes, vem a achar-se num estado especial que faculta ao Espírito ver o que não podeis ver com os olhos carnais." Nas épocas de crises e de calamidades, as grandes emoções, todas as causas, enfim, de superexcitação do moral provocam não raro o desenvolvimento da dupla vista. Parece que a Providência, quando um perigo nos ameaça, nos dá o meio de conjurá-lo. Todas as seitas e partidos perseguidos oferecem múltiplos exemplos desse fato.', 'rascunho'),
  (453, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'As pessoas dotadas de dupla vista sempre têm consciência de que a possuem?', 'Nem sempre. Consideram isso coisa perfeitamente natural e muitos crêem que, se cada um observasse o que se passa consigo, todos verificariam que são como eles.', 'rascunho'),
  (454, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Poder-se-ia atribuir a uma espécie de segunda vista a perspicácia de algumas pessoas que, sem nada apresentarem de extraordinário, apreciam as coisas com mais precisão do que outras?', 'É sempre a alma a irradiar mais livremente e a apreciar melhor do que sob o véu da matéria." a) — Pode esta faculdade, em alguns casos, dar a presciência das coisas? "Pode. Também dá os pressentimentos, pois que muitos são os graus em que ela existe, sendo possível que num mesmo indivíduo exista em todos os graus, ou em alguns somente.', 'rascunho'),
  (455, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo VIII — Da emancipação da alma', 'Questão 455', 'Os fenômenos do sonambulismo natural se produzem espontaneamente e independem de qualquer causa exterior conhecida. Mas, em certas pessoas dotadas de especial organização, podem ser provocados artificialmente, pela ação do agente magnético. O estado que se designa pelo nome de sonambulismo magnético apenas difere do sonambulismo natural em que um é provocado, enquanto o outro é espontâneo. O sonambulismo natural constitui fato notório, que ninguém mais se lembra de pôr em dúvida, não obstante o aspecto maravilhoso dos fenômenos a que dá lugar. Por que seria então mais extraordinário ou irracional o sonambulismo magnético? Apenas por produzir-se artificialmente, como tantas outras coisas? Os charlatães o exploram, dizem. Razão demais para que não lhes seja deixado nas mãos. Quando a Ciência se houver apropriado dele, muito menos crédito terão os charlatães junto às massas populares. Enquanto isso não se verifica, como o sonambulismo natural ou artificial é um fato, e como contra fatos não há raciocínio possível, vai ele ganhando terreno, apesar da má vontade de alguns, no seio da própria Ciência, onde penetra por uma imensidade de portinhas, em vez de entrar pela porta larga. Quando lá estiver totalmente, terão que lhe conceder direito de cidade. Para o Espiritismo, o sonambulismo é mais do que um fenômeno psicológico, é uma luz projetada sobre a psicologia. É aí que se pode estudar a alma, porque é onde esta se mostra a descoberto. Ora, um dos fenômenos que a caracterizam é o da clarividência independente dos órgãos ordinários da vista. Fundam-se os que contestam este fato em que o sonâmbulo nem sempre vê, e à vontade do experimentador, como com os olhos. Será de admirar que difiram os efeitos, quando diferentes são os meios? Será racional que se pretenda obter os mesmos efeitos, quando há e quando não há o instrumento? A alma tem suas propriedades, como os olhos têm as suas. Cumpre julgá-las em si mesmas e não por analogia. De uma causa única se originam a clarividência do sonâmbulo magnético e a do sonâmbulo natural. É um atributo da alma, uma faculdade inerente a todas as partes do ser incorpóreo que existe em nós e cujos limites não são outros senão os assinados à própria alma. O sonâmbulo vê em todos os lugares aonde sua alma possa transportar-se, qualquer que seja a longitude. 166 – Allan Kar dec No caso de visão a distância, o sonâmbulo não vê as coisas de onde está o seu corpo, como por meio de um telescópio. Vê-as presentes, como se se achasse no lugar onde elas existem, porque sua alma, em realidade, lá está. Por isso é que seu corpo fica como que aniquilado e privado de sensação, até que a alma volte a habitá-lo novamente. Essa separação parcial da alma e do corpo constitui um estado anormal, suscetível de duração mais ou menos longa, porém não indefinida. Daí a fadiga que o corpo experimenta após certo tempo, mormente quando aquela se entrega a um trabalho ativo. A vista da alma ou do Espírito não é circunscrita e não tem sede determinada. Eis por que os sonâmbulos não lhe podem marcar órgão especial. Vêem porque vêem, sem saberem o motivo nem o modo, uma vez que, para eles, na condição de Espíritos, a vista carece de foco próprio. Se se reportam ao corpo, esse foco lhes parece estar nos centros onde maior é a atividade vital, principalmente no cérebro, na região do epigastro, ou no órgão que considerem o ponto de ligação mais forte entre o Espírito e o corpo. O poder da lucidez sonambúlica não é ilimitado. O Espírito, mesmo quando completamente livre, tem restringidos seus conhecimentos e faculdades, conforme ao grau de perfeição que haja alcançado. Ainda mais restringidos os tem quando ligado à matéria, a cuja influência está sujeito. É o que motiva não ser universal, nem infalível, a clarividência sonambúlica. E tanto menos se pode contar com a sua infalibilidade, quanto mais desviada seja do fim visado pela natureza e transformada em objeto de curiosidade e de experimentação. No estado de desprendimento em que fica colocado, o Espírito do sonâmbulo entra em comunicação mais fácil com os outros Espíritos encarnados, ou não encarnados, comunicação que se estabelece pelo contacto dos fluidos, que compõem os perispíritos e servem de transmissão ao pensamento, como o fio elétrico. O sonâmbulo não precisa, portanto, que se lhe exprimam os pensamentos por meio da palavra articulada. Ele os sente e adivinha. É o que o torna eminentemente impressionável e sujeito às influências da atmosfera moral que o envolva. Essa também a razão por que uma assistência muito numerosa e a presença de curiosos mais ou menos malevolentes lhe prejudicam de modo essencial o desenvolvimento das faculdades que, por assim dizer, se contraem, só se desdobrando com toda a liberdade num meio íntimo ou simpático. A presença de pessoas mal-intencionadas ou antipáticas lhe produz efeito idêntico ao do contacto da mão na sensitiva. O sonâmbulo vê ao mesmo tempo o seu próprio Espírito e o seu corpo, os quais constituem, por assim dizer, dois seres que lhe representam a dupla existência corpórea e espiritual, existências que, entretanto, se confundem, mediante os laços que as unem. Nem sempre o sonâmbulo se apercebe de tal situação e essa dualidade faz que muitas vezes fale de si, como se falasse de outra pessoa. É que ora é o ser corpóreo que fala ao ser espiritual, ora é este que fala àquele. Em cada uma de suas existências corporais, o Espírito adquire um acréscimo de conhecimentos e de experiência. Esquece-os parcialmente, quando encarnado em matéria por demais grosseira, porém deles se recorda como Espírito. Assim é que certos sonâmbulos revelam conhecimentos acima do grau da instrução que possuem e mesmo superiores às suas aparentes capacidades intelectuais. Portanto, da inferioridade intelectual e científica do sonâmbulo, quando desperto, nada se pode inferir com relação aos conhecimentos que porventura revele no estado de lucidez. Conforme as circunstâncias e o fim que se tenha em vista, ele os pode haurir da sua própria experiência, da sua clarividência relativa às coisas presentes, ou dos conselhos que receba de outros Espíritos. Mas, podendo o seu próprio Espírito ser mais ou menos adiantado, possível lhe é dizer coisas mais ou menos certas. Pelos fenômenos do sonambulismo, quer natural, quer magnético, a Providência nos dá a prova irrecusável da existência e da independência da alma e nos faz assistir ao sublime espetáculo da sua emancipação. Abre-nos, dessa maneira, o livro do nosso destino. Quando o sonâmbulo descreve o que se passa a distância, é evidente que vê, mas não com os olhos do corpo. Vê-se a si mesmo e se sente transportado ao lugar onde vê o que descreve. Lá se acha, pois, alguma coisa dele e, não podendo essa alguma coisa ser o seu corpo, necessariamente é sua alma, ou Espírito. Enquanto o homem se perde nas sutilezas de uma metafísica abstrata e ininteligível, em busca das causas da nossa existência moral, Deus cotidianamente nos põe sob os olhos e ao alcance da mão os mais simples e patentes meios de estudarmos a psicologia experimental. O êxtase é o estado em que a independência da alma, com relação ao corpo, se manifesta de modo mais sensível e se torna, de certa forma, palpável. No sonho e no sonambulismo, o Espírito anda em giro pelos mundos terrestres. No êxtase, penetra em um mundo desconhecido, o dos Espíritos etéreos, com os quais entra em comunicação, sem que, todavia, lhe seja lícito ultrapassar certos limites, porque, se os transpusesse, totalmente se partiriam os laços que o prendem ao corpo. Cerca-o então resplendente e desusado fulgor, inebriam-no harmonias que na Terra se desconhecem, indefinível bem-estar o invade: goza antecipadamente da beatitude celeste e bem se pode dizer que pousa um pé no limiar da eternidade. No estado de êxtase, o aniquilamento do corpo é quase completo. Fica-lhe somente, pode-se dizer, a vida orgânica. Sente-se que a alma se lhe acha presa unicamente por um fio, que mais um pequenino esforço quebraria sem remissão. Nesse estado, desaparecem todos os pensamentos terrestres, cedendo lugar ao sentimento apurado, que constitui a essência mesma do nosso ser imaterial. Inteiramente entregue a tão sublime contemplação, o extático encara a vida apenas como paragem momentânea. Considera os bens e os males, as alegrias grosseiras e as misérias deste mundo quais incidentes fúteis de uma viagem, cujo termo tem a dita de avistar. Dá-se com os extáticos o que se dá com os sonâmbulos: mais ou menos perfeita podem ter a lucidez e o Espírito mais ou menos apto a conhecer e compreender as coisas, conforme seja mais ou menos elevado. Muitas vezes, porém, há neles mais excitação do que verdadeira lucidez, ou, melhor, muitas vezes a exaltação lhes prejudica a lucidez. Daí o serem, freqüentemente, suas revelações um misto de verdades e erros, de coisas grandiosas e coisas absurdas, até ridículas. Dessa exaltação, que é sempre uma causa de fraqueza, quando o indivíduo não sabe reprimi-la, Espíritos inferiores costumam aproveitar-se para dominar o extático, tomando, com tal intuito, aos seus olhos, aparências que mais o aferram às idéias 168 – Allan Kar dec que nutre no estado de vigília. Há nisso um escolho, mas nem todos são assim. Cabe-nos tudo julgar friamente e pesar-lhes as revelações na balança da razão. A emancipação da alma se verifica às vezes no estado de vigília e produz o fenômeno conhecido pelo nome de segunda vista ou dupla vista, que é a faculdade graças à qual quem a possui vê, ouve e sente além dos limites dos sentidos humanos. Percebe o que exista até onde estende a alma a sua ação. Vê, por assim dizer, através da vista ordinária e como por uma espécie de miragem. No momento em que o fenômeno da segunda vista se produz, o estado físico do indivíduo se acha sensivelmente modificado. O olhar apresenta alguma coisa de vago. Ele olha sem ver. Toda a sua fisionomia reflete uma como exaltação. Nota-se que os órgãos visuais se conservam alheios ao fenômeno, pelo fato de a visão persistir, malgrado à oclusão dos olhos. Aos dotados desta faculdade ela se afigura tão natural, como a que todos temos de ver. Consideram-na um atributo de seus próprios seres, que em nada lhes parecem excepcionais. De ordinário, o esquecimento se segue a essa lucidez passageira, cuja lembrança, tornando-se cada vez mais vaga, acaba por desaparecer, como a de um sonho. O poder da vista dupla varia, indo desde a sensação confusa até a percepção clara e nítida das coisas presentes ou ausentes. Quando rudimentar, confere a certas pessoas o tato, a perspicácia, uma certa segurança nos atos, a que se pode dar o qualificativo de precisão de golpe de vista moral. Um pouco desenvolvida, desperta os pressentimentos. Mais desenvolvida mostra os acontecimentos que deram ou estão para dar-se. O sonambulismo natural e artificial, o êxtase e a dupla vista são efeitos vários, ou de modalidades diversas, de uma mesma causa. Esses fenômenos, como os sonhos, estão na ordem da natureza. Tal a razão por que hão existido em todos os tempos. A História mostra que foram sempre conhecidos e até explorados desde a mais remota antiguidade e neles se nos depara a explicação de uma imensidade de fatos que os preconceitos fizeram fossem tidos por sobrenaturais.', 'rascunho'),
  (456, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Vêem os Espíritos tudo o que fazemos?', 'Podem ver, pois que constantemente vos rodeiam. Cada um, porém, só vê aquilo a que dá atenção. Não se ocupam com o que lhes é indiferente.', 'rascunho'),
  (457, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Podem os Espíritos conhecer os nossos mais secretos pensamentos?', 'Muitas vezes chegam a conhecer o que desejaríeis ocultar de vós mesmos. Nem atos, nem pensamentos se lhes podem dissimular." a) — Assim, mais fácil nos seria ocultar de uma pessoa viva qualquer coisa, do que a esconder dessa mesma pessoa depois de morta? 170 – Allan Kar dec "Certamente. Quando vos julgais muito ocultos, é comum terdes ao vosso lado uma multidão de Espíritos que vos observam.', 'rascunho'),
  (458, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Que pensam de nós os Espíritos que nos cercam e observam?', 'Depende. Os levianos riem das pequenas partidas que vos pregam e zombam das vossas impaciências. Os Espíritos sérios se condoem dos vossos reveses e procuram ajudar-vos.', 'rascunho'),
  (459, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Influem os Espíritos em nossos pensamentos e em nossos atos?', 'Muito mais do que imaginais. Influem a tal ponto, que, de ordinário, são eles que vos dirigem.', 'rascunho'),
  (460, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'De par com os pensamentos que nos são próprios, outros haverá que nos sejam sugeridos?', 'Vossa alma é um Espírito que pensa. Não ignorais que, freqüentemente, muitos pensamentos vos acodem a um tempo sobre o mesmo assunto e, não raro, contrários uns aos outros. Pois bem! No conjunto deles, estão sempre de mistura os vossos com os nossos. Daí a incerteza em que vos vedes. É que tendes em vós duas idéias a se combaterem.', 'rascunho'),
  (461, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Como havemos de distinguir os pensamentos que nos são próprios dos que nos são sugeridos?', 'Quando um pensamento vos é sugerido, tendes a impressão de que alguém vos fala. Geralmente, os pensamentos próprios são os que acodem em primeiro lugar. Afinal, não vos é de grande interesse estabelecer essa distinção. Muitas vezes, é útil que não saibais fazê-la. Não a fazendo, obra o homem com mais liberdade. Se se decide pelo bem, é voluntariamente que o pratica; se toma o mau caminho, maior será a sua responsabilidade.', 'rascunho'),
  (462, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'É sempre de dentro de si mesmos que os homens inteligentes e de gênio tiram suas idéias?', 'Algumas vezes, elas lhes vêm do seu próprio Espírito, porém, de outras muitas, lhes são sugeridas por Espíritos que os julgam capazes de compreendê-las e dignos de vulgarizá-las. Quando tais homens não as acham em si mesmos, apelam para a inspiração. Fazem assim, sem o suspeitarem, uma verdadeira evocação." Se fora útil que pudéssemos distinguir claramente os nossos pensamentos próprios dos que nos são sugeridos, Deus nos houvera proporcionado os meios de o conseguirmos, como nos concedeu o de diferençarmos o dia da noite. Quando uma coisa se conserva imprecisa, é que convém assim aconteça.', 'rascunho'),
  (463, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Diz-se comumente ser sempre bom o primeiro impulso. É exato?', 'Pode ser bom ou mau, conforme a natureza do Espírito encarnado. É sempre bom naquele que atende às boas inspirações.', 'rascunho'),
  (464, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Como distinguirmos se um pensamento sugerido procede de um bom Espírito ou de um Espírito mau?', 'Estudai o caso. Os bons Espíritos só para o bem aconselham. Compete-vos discernir.', 'rascunho'),
  (465, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Com que fim os Espíritos imperfeitos nos induzem ao mal?', 'Para que sofrais como eles sofrem." a) — E isso lhes diminui os sofrimentos? "Não; mas fazem-no por inveja, por não poderem suportar que haja seres felizes." b) — De que natureza é o sofrimento que procuram infligir aos outros? "Os que resultam de ser de ordem inferior a criatura e de estar afastada de Deus.', 'rascunho'),
  (466, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Por que permite Deus que Espíritos nos excitem ao mal?', 'Os Espíritos imperfeitos são instrumentos próprios a pôr em prova a fé e a constância dos homens na prática do bem. Como Espírito que és, tens que progredir na ciência do infinito. Daí o passares pelas provas do mal, para chegares ao bem. A nossa missão consiste em te colocarmos no bom caminho. Desde que sobre ti atuam influências más, é que as atrais, desejando o mal; porquanto os Espíritos inferiores correm a te auxiliar no mal, logo que desejes praticá-lo. Só quando queiras o mal, podem eles ajudar-te para a prática do mal. Se fores propenso ao assassínio, terás em torno de ti uma nuvem de Espíritos a te alimentarem no íntimo esse pendor. Mas, outros também te cercarão, esforçando-se por te influenciarem para o bem, o que restabelece o equilíbrio da balança e te deixa senhor dos teus atos." É assim que Deus confia à nossa consciência a escolha do caminho que devamos seguir e a liberdade de ceder a uma ou outra das influências contrárias que se exercem sobre nós.', 'rascunho'),
  (467, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Pode o homem eximir-se da influência dos Espíritos que procuram arrastá-lo ao mal?', 'Pode, visto que tais Espíritos só se apegam aos que, pelos seus desejos, os chamam, ou aos que, pelos seus pensamentos, os atraem.', 'rascunho'),
  (468, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Renunciam às suas tentativas os Espíritos cuja influência a vontade do homem repele?', 'Que querias que fizessem? Quando nada conseguem, abandonam o campo. Entretanto, ficam à espreita de um momento propício, como o gato que tocaia o rato.', 'rascunho'),
  (469, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Por que meio podemos neutralizar a influência dos maus Espíritos?', 'Praticando o bem e pondo em Deus toda a vossa confiança, repelireis a influência dos Espíritos inferiores e aniquilareis o império que desejem ter sobre vós. Guardai-vos de atender às sugestões dos Espíritos que vos suscitam maus 172 – Allan Kar dec pensamentos, que sopram a discórdia entre vós outros e que vos insuflam as paixões más. Desconfiai especialmente dos que vos exaltam o orgulho, pois que esses vos assaltam pelo lado fraco. Essa a razão por que Jesus, na oração dominical, vos ensinou a dizer: "Senhor! não nos deixes cair em tentação, mas livra-nos do mal.', 'rascunho'),
  (470, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Os Espíritos, que ao mal procuram induzir-nos e que põem assim em prova a nossa firmeza no bem, procedem desse modo cumprindo missão? E, se assim é, cabe-lhes alguma responsabilidade?', 'A nenhum Espírito é dada a missão de praticar o mal. Aquele que o faz fá- lo por conta própria, sujeitando-se, portanto, às conseqüências. Pode Deus permitir- lhe que assim proceda, para vos experimentar; nunca, porém, lhe determina tal procedimento. Compete-vos, pois, repeli-lo.', 'rascunho'),
  (471, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Quando experimentamos uma sensação de angústia, de ansiedade indefinível, ou de íntima satisfação, sem que lhe conheçamos a causa, devemos atribuí-la unicamente a uma disposição física?', 'É quase sempre efeito das comunicações em que inconscientemente entrais com os Espíritos, ou da que com eles tivestes durante o sono.', 'rascunho'),
  (472, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Os Espíritos que procuram atrair-nos para o mal se limitam a aproveitar as circunstâncias em que nos achamos, ou podem também criá-las?', 'Aproveitam as circunstâncias ocorrentes, mas também costumam criá-las, impelindo-vos, mau grado vosso, para aquilo que cobiçais. Assim, por exemplo, encontra um homem, no seu caminho, certa quantia. Não penses tenham sido os Espíritos que a trouxeram para ali. Mas, eles podem inspirar ao homem a idéia de tomar aquela direção e sugerir-lhe depois a de se apoderar da importância achada, enquanto outros lhe sugerem a de restituir o dinheiro ao seu legítimo dono. O mesmo se dá com relação a todas as demais tentações.', 'rascunho'),
  (473, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Pode um Espírito tomar temporariamente o invólucro corporal de uma pessoa viva, isto é, introduzir-se num corpo animado e obrar em lugar do outro que se acha encarnado neste corpo?', 'O Espírito não entra em um corpo como entras numa casa. Identifica-se com um Espírito encarnado, cujos defeitos e qualidades sejam os mesmos que os seus, a fim de obrar conjuntamente com ele. Mas, o encarnado é sempre quem atua, conforme quer, sobre a matéria de que se acha revestido. Um Espírito não pode substituir-se ao que está encarnado, por isso que este terá que permanecer ligado ao seu corpo até ao termo fixado para sua existência material.', 'rascunho'),
  (474, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Desde que não há possessão propriamente dita, isto é, coabitação de dois Espíritos no mesmo corpo, pode a alma ficar na dependência de outro Espírito, de modo a se achar subjugada ou obsidiada ao ponto de a sua vontade vir a achar-se, de certa maneira, paralisada?', 'Sem dúvida e são esses os verdadeiros possessos. Mas, é preciso saibas que essa dominação não se efetua nunca sem que aquele que a sofre o consinta, quer por sua fraqueza, quer por desejá-la. Muitos epilépticos ou loucos, que mais necessitavam de médico que de exorcismos, têm sido tomados por possessos." O vocábulo possesso, na sua acepção vulgar, supõe a existência de demônios, isto é, de uma categoria de seres maus por natureza, e a coabitação de um desses seres com a alma de um indivíduo, no seu corpo. Pois que, nesse sentido, não há demônios e que dois Espíritos não podem habitar simultaneamente o mesmo corpo, não há possessos na conformidade da idéia a que esta palavra se acha associada. O termo possesso só se deve admitir como exprimindo a dependência absoluta em que uma alma pode achar-se com relação a Espíritos imperfeitos que a subjuguem.', 'rascunho'),
  (475, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Pode alguém por si mesmo afastar os maus Espíritos e libertar-se da dominação deles?', 'Sempre é possível, a quem quer que seja, subtrair-se a um jugo, desde que com vontade firme o queira.', 'rascunho'),
  (476, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Mas, não pode acontecer que a fascinação exercida pelo mau Espírito seja de tal ordem que o subjugado não a perceba? Sendo assim, poderá uma terceira pessoa fazer que cesse a sujeição da outra? E, nesse caso, qual deve ser a condição dessa terceira pessoa?', 'Sendo ela um homem de bem, a sua vontade poderá ter eficácia, desde que apele para o concurso dos bons Espíritos, porque, quanto mais digna for a pessoa, tanto maior poder terá sobre os Espíritos imperfeitos, para afastá-los, e sobre os bons, para os atrair. Todavia, nada poderá, se o que estiver subjugado não lhe prestar o seu concurso. Há pessoas a quem agrada uma dependência que lhes lisonjeia os gostos e os desejos. Qualquer, porém, que seja o caso, aquele que não tiver puro o coração nenhuma influência exercerá. Os bons Espíritos não lhe atendem ao chamado e os maus não o temem.', 'rascunho'),
  (477, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'As fórmulas de exorcismo têm qualquer eficácia sobre os maus Espíritos?', 'Não. Estes últimos riem e se obstinam, quando vêem alguém tomar isso a sério.', 'rascunho'),
  (478, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Pessoas há, animadas de boas intenções e que, nada obstante, não deixam de ser obsidiadas. Qual, então, o melhor meio de nos livrarmos dos Espíritos obsessores?', 'Cansar-lhes a paciência, nenhum valor lhes dar às sugestões, mostrar-lhes que perdem o tempo. Em vendo que nada conseguem, afastam-se.', 'rascunho'),
  (479, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'A prece é meio eficiente para a cura da obsessão?', 'A prece é em tudo um poderoso auxílio. Mas, crede que não basta que alguém murmure algumas palavras, para que obtenha o que deseja. Deus assiste os que obram, não os que se limitam a pedir. É, pois, indispensável que o obsidiado faça, por sua parte, o que se torne necessário para destruir em si mesmo a causa da atração dos maus Espíritos." 174 – Allan Kar dec', 'rascunho'),
  (480, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Que se deve pensar da expulsão dos demônios, mencionada no Evangelho?', 'Depende da interpretação que se lhe dê. Se chamais demônio ao mau Espírito que subjugue um indivíduo, desde que se lhe destrua a influência, ele terá sido verdadeiramente expulso. Se ao demônio atribuirdes a causa de uma enfermidade, quando a houverdes curado direis com acerto que expulsastes o demônio. Uma coisa pode ser verdadeira ou falsa, conforme o sentido que empresteis às palavras. As maiores verdades estão sujeitas a parecer absurdos, uma vez que se atenda apenas à forma, ou que se considere como realidade a alegoria. Compreendei bem isto e não o esqueçais nunca, pois que se presta a uma aplicação geral.', 'rascunho'),
  (481, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Desempenham os Espíritos algum papel nos fenômenos que se dão com os indivíduos chamados convulsionários?', 'Sim e muito importante, bem como o magnetismo, que é a causa originária de tais fenômenos. O charlatanismo, porém, os tem amiúde explorado e exagerado, de sorte a lançá-los ao ridículo." a) — De que natureza são, em geral, os Espíritos que concorrem para a produção desta espécie de fenômenos? "Pouco elevada. Supondes que Espíritos superiores se deleitem com tais coisas?', 'rascunho'),
  (482, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Como é que sucede estender-se subitamente a toda uma população o estado anormal dos convulsionários e dos que sofrem de crises nervosas?', 'Efeito de simpatia. As disposições morais se comunicam mui facilmente, em certos casos. Não és tão alheio aos efeitos magnéticos que não compreendas isto e a parte que alguns Espíritos naturalmente tomam no fato, por simpatia com os que os provocam." Entre as singulares faculdades que se notam nos convulsionários, algumas facilmente se reconhecem, de que numerosos exemplos oferecem o sonambulismo e o magnetismo, tais como, além de outras, a insensibilidade física, a leitura do pensamento, a transmissão das dores, por simpatia, etc. Não há, pois, duvidar de que aqueles em quem tais crises se manifestam estejam numa espécie de sonambulismo desperto, provocado pela influência que exercem uns sobre os outros. Eles são ao mesmo tempo magnetizadores e magnetizados, inconscientemente.', 'rascunho'),
  (483, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Qual a causa da insensibilidade física que se observa em alguns convulsionários, assim como em outros indivíduos submetidos às mais atrozes torturas?', 'Em alguns é, exclusivamente, efeito do magnetismo, que atua sobre o sistema nervoso, do mesmo modo que certas substâncias. Em outros, a exaltação do pensamento embota a sensibilidade. Dir-se-ia que nestes a vida se retirou do corpo, para se concentrar toda no Espírito. Não sabeis que, quando o Espírito está vivamente preocupado com uma coisa, o corpo nada sente, nada vê e nada ouve?" A exaltação fanática e o entusiasmo hão proporcionado, em casos de suplícios, múltiplos exemplos de uma calma e de um sangue frio que não seriam capazes de triunfar de uma dor aguda, senão admitindo-se que a sensibilidade se acha neutralizada, como por efeito de um anestésico. Sabe-se que, no ardor da batalha, combatentes há que não se apercebem de que estão gravemente feridos, ao passo que, em circunstâncias ordinárias, uma simples arranhadura os poria trêmulos. Visto que esses fenômenos dependem de uma causa física e da ação de certos Espíritos, lícito se torna perguntar como há podido uma autoridade pública fazê-los cessar em alguns casos. Simples a razão. Meramente secundária é aqui a ação dos Espíritos, que nada mais fazem do que aproveitar-se de uma disposição natural. A autoridade não suprimiu essa disposição, mas a causa que a entretinha e exaltava. De ativa que era, passou esta a ser latente. E a autoridade teve razão para assim proceder, porque do fato resultava abuso e escândalo. Sabe-se, demais, que semelhante intervenção nenhum poder absolutamente tem, quando a ação dos Espíritos é direta e espontânea.', 'rascunho'),
  (484, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Os Espíritos se afeiçoam de preferência a certas pessoas?', 'Os bons Espíritos simpatizam com os homens de bem, ou suscetíveis de se melhorarem. Os Espíritos inferiores com os homens viciosos, ou que podem tornar- se tais. Daí suas afeições, como conseqüência da conformidade dos sentimentos.', 'rascunho'),
  (485, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'É exclusivamente moral a afeição que os Espíritos votam a certas pessoas?', 'A verdadeira afeição nada tem de carnal; mas, quando um Espírito se apega a uma pessoa, nem sempre o faz só por afeição. À estima que essa pessoa lhe inspira pode agregar-se uma reminiscência das paixões humanas.', 'rascunho'),
  (486, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Interessam-se os Espíritos pelas nossas desgraças e pela nossa prosperidade? Afligem-se os que nos querem bem com os males que padecemos durante a vida?', 'Os bons Espíritos fazem todo o bem que lhes é possível e se sentem ditosos com as vossas alegrias. Afligem-se com os vossos males, quando os não suportais com resignação, porque nenhum benefício então tirais deles, assemelhando-vos, em tais casos, ao doente que rejeita a beberagem amarga que o há de curar.', 'rascunho'),
  (487, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Dentre os nossos males, de que natureza são os de que mais se afligem os Espíritos por nossa causa? Serão os males físicos ou os morais?', 'O vosso egoísmo e a dureza dos vossos corações. Daí decorre tudo o mais. Riem-se de todos esses males imaginários que nascem do orgulho e da ambição. Rejubilam com os que redundam na abreviação do tempo das vossas provas." Sabendo ser transitória a vida corporal e que as tribulações que lhe são inerentes constituem meios de alcançarmos melhor estado, os Espíritos mais se afligem pelos nossos 176 – Allan Kar dec males devidos a causas de ordem moral, do que pelos nossos sofrimentos físicos, todos passageiros. Pouco se incomodam com as desgraças que apenas atingem as nossas idéias mundanas, tal qual fazemos com as mágoas pueris das crianças. Vendo nas amarguras da vida um meio de nos adiantarmos, os Espíritos as consideram como a crise ocasional de que resultará a salvação do doente. Compadecem-se dos nossos sofrimentos, como nos compadecemos dos de um amigo. Porém, enxergando as coisas de um ponto de vista mais justo, os apreciam de um modo diverso do nosso. Então, ao passo que os bons nos levantam o ânimo no interesse do nosso futuro, os outros nos impelem ao desespero, objetivando comprometer-nos.', 'rascunho'),
  (488, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Os parentes e amigos, que nos precederam na outra vida, maior simpatia nos votam do que os Espíritos que nos são estranhos?', 'Sem dúvida e quase sempre vos protegem como Espíritos, de acordo com o poder de que dispõem." a) — São sensíveis à afeição que lhes conservamos? "Muito sensíveis, mas esquecem-se dos que os olvidam.', 'rascunho'),
  (489, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Há Espíritos que se liguem particularmente a um indivíduo para protegê-lo?', 'Há o irmão espiritual, o que chamais o bom Espírito ou o bom gênio.', 'rascunho'),
  (490, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Que se deve entender por anjo de guarda ou anjo guardião?', 'O Espírito protetor, pertencente a uma ordem elevada.', 'rascunho'),
  (491, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Qual a missão do Espírito protetor?', 'A de um pai com relação aos filhos; a de guiar o seu protegido pela senda do bem, auxiliá-lo com seus conselhos, consolá-lo nas suas aflições, levantar-lhe o ânimo nas provas da vida.', 'rascunho'),
  (492, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'O Espírito protetor se dedica ao indivíduo desde o seu nascimento?', 'Desde o nascimento até a morte e muitas vezes o acompanha na vida espírita, depois da morte, e mesmo através de muitas existências corpóreas, que mais não são do que fases curtíssimas da vida do Espírito.', 'rascunho'),
  (493, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'É voluntária ou obrigatória a missão do Espírito protetor?', 'O Espírito fica obrigado a vos assistir, uma vez que aceitou esse encargo. Cabe-lhe, porém, o direito de escolher seres que lhe sejam simpáticos. Para alguns, é um prazer; para outros, missão ou dever." a) — Dedicando-se a uma pessoa, renuncia o Espírito a proteger outros indivíduos? "Não; mas protege-os menos exclusivamente.', 'rascunho'),
  (494, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'O Espírito protetor fica fatalmente preso à criatura confiada à sua guarda?', 'Freqüentemente sucede que alguns Espíritos deixam suas posições de protetores para desempenhar diversas missões. Mas, nesse caso, outros os substituem.', 'rascunho'),
  (495, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Poderá dar-se que o Espírito protetor abandone o seu protegido, por se lhe mostrar este rebelde aos conselhos?', 'Afasta-se, quando vê que seus conselhos são inúteis e que mais forte é, no seu protegido, a decisão de submeter-se à influência dos Espíritos inferiores. Mas, não o abandona completamente e sempre se faz ouvir. É então o homem quem tapa os ouvidos. O protetor volta desde que este o chame." "É uma doutrina, esta, dos anjos guardiães, que, pelo seu encanto e doçura, devera converter os mais incrédulos. Não vos parece grandemente consoladora a idéia de terdes sempre junto de vós seres que vos são superiores, prontos sempre a vos aconselhar e amparar, a vos ajudar na ascensão da abrupta montanha do bem; mais sinceros e dedicados amigos do que todos os que mais intimamente se vos liguem na Terra? Eles se acham ao vosso lado por ordem de Deus. Foi Deus quem aí os colocou e, aí permanecendo por amor de Deus, desempenham bela, porém penosa missão. Sim, onde quer que estejais, estarão convosco. Nem nos cárceres, nem nos hospitais, nem nos lugares de devassidão, nem na solidão, estais separados desses amigos a quem não podeis ver, mas cujo brando influxo vossa alma sente, ao mesmo tempo que lhes ouve os ponderados conselhos." "Ah! se conhecêsseis bem esta verdade! Quanto vos ajudaria nos momentos de crise! Quanto vos livraria dos maus Espíritos! Mas, oh! quantas vezes, no dia solene, não se verá esse anjo constrangido a vos observar: ‘Não te aconselhei isto? Entretanto, não o fizeste. Não te mostrei o abismo? Contudo, nele te precipitaste! Não fiz ecoar na tua consciência a voz da verdade? Preferiste, no entanto, seguir os conselhos da mentira!’ Oh! interrogai os vossos anjos guardiães; estabelecei entre eles e vós essa terna intimidade que reina entre os melhores amigos. Não penseis em lhes ocultar nada, pois que eles têm o olhar de Deus e não podeis enganá-los. Pensai no futuro; procurai adiantar-vos na vida presente. Assim fazendo, encurtareis vossas provas e mais felizes tornareis as vossas existências. Vamos, homens, coragem! De uma vez por todas, lançai para longe todos os preconceitos e idéias preconcebidas. Entrai na nova senda que diante dos passos se vos abre. Caminhai! Tendes guias, segui-os, que a meta não vos pode faltar, porquanto essa meta é o próprio Deus." "Aos que considerem impossível que Espíritos verdadeiramente elevados se consagrem a tarefa tão laboriosa e de todos os instantes, diremos que nós vos influenciamos as almas, estando embora muitos milhões de léguas distantes de vós. O espaço, para nós, nada é, e, não obstante viverem noutro mundo, os nossos Espíritos conservam suas ligações com os vossos. Gozamos de qualidades que não podeis compreender, mas ficai certos de que Deus não nos impôs tarefa superior às nossas forças e de que não vos deixou sós na Terra, sem amigos e sem amparo. Cada anjo de guarda tem o seu protegido, pelo qual vela, como o pai pelo filho. Alegra-se, quando o vê no bom caminho; sofre, quando ele lhe despreza os conselhos." "Não receeis fatigar-nos com as vossas perguntas. Ao contrário, procurai estar sempre em relação conosco. Sereis assim mais fortes e mais felizes. São essas 178 – Allan Kar dec comunicações de cada um com o seu Espírito familiar que fazem sejam médiuns todos os homens, médiuns ignorados hoje, mas que se manifestarão mais tarde e se espalharão qual oceano sem margens, levando de roldão a incredulidade e a ignorância. Homens doutos, instruí os vossos semelhantes; homens de talento, educai os vossos irmãos. Não imaginais que obra fazeis desse modo: a do Cristo, a que Deus vos impõe. Para que vos outorgou Deus a inteligência e o saber, senão para os repartirdes com os vossos irmãos, senão para fazerdes que se adiantem pela senda que conduz à bem-aventurança, à felicidade eterna?', 'rascunho'),
  (496, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'O Espírito, que abandona o seu protegido, que deixa de lhe fazer bem, pode fazer-lhe mal?', 'Os bons Espíritos nunca fazem mal. Deixam que o façam aqueles que lhes tomam o lugar. Costumais então lançar à conta da sorte as desgraças que vos acabrunham, quando só as sofreis por culpa vossa.', 'rascunho'),
  (497, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Pode um Espírito protetor deixar o seu protegido à mercê de outro Espírito que lhe queira fazer mal?', 'Os maus Espíritos se unem para neutralizar a ação dos bons. Mas, se o quiser, o protegido dará toda a força ao seu protetor. Pode acontecer que o bom Espírito encontre alhures uma boa vontade a ser auxiliada. Aplica-se então em auxiliá-la, aguardando que seu protegido lhe volte.', 'rascunho'),
  (498, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Será por não poder lutar contra Espíritos malévolos que um Espírito protetor deixa que seu protegido se transvie na vida?', 'Não é porque não possa, mas porque não quer. E não quer, porque das provas sai o seu protegido mais instruído e perfeito. Assiste-o sempre com seus conselhos, dando-os por meio dos bons pensamentos que lhe inspira, porém que quase nunca são atendidos. A fraqueza, o descuido ou o orgulho do homem são exclusivamente o que empresta força aos maus Espíritos, cujo poder todo advém do fato de lhes não opordes resistência.', 'rascunho'),
  (499, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'O Espírito protetor está constantemente com o seu protegido? Não haverá alguma circunstância em que, sem abandoná-lo, ele o perca de vista?', 'Há circunstâncias em que não é necessário esteja o Espírito protetor junto do seu protegido.', 'rascunho'),
  (500, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Momentos haverá em que o Espírito deixe de precisar, de então por diante, do seu protetor?', 'Sim, quando ele atinge o ponto de poder guiar-se a si mesmo, como sucede ao estudante, para o qual um momento chega em que não mais precisa de mestre. Isso, porém, não se dá na Terra.', 'rascunho'),
  (501, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Por que é oculta a ação dos Espíritos sobre a nossa existência e por que, quando nos protegem, não o fazem de modo ostensivo?', 'Se vos fosse dado contar sempre com a ação deles, não obraríeis por vós mesmos e o vosso Espírito não progrediria. Para que este possa adiantar-se, precisa de experiência, adquirindo-a freqüentemente à sua custa. É necessário que exercite suas forças, sem o que, seria como a criança a quem não consentem que ande sozinha. A ação dos Espíritos que vos querem bem é sempre regulada de maneira que não vos tolha o livre-arbítrio, porquanto, se não tivésseis responsabilidade, não avançaríeis na senda que vos há de conduzir a Deus. Não vendo quem o ampara, o homem se confia às suas próprias forças. Sobre ele, entretanto, vela o seu guia e, de tempos a tempos, lhe brada, advertindo-o do perigo.', 'rascunho'),
  (502, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'O Espírito protetor, que consegue trazer ao bom caminho o seu protegido, lucra algum bem para si?', 'Constitui isso um mérito que lhe é levado em conta, seja para seu progresso, seja para sua felicidade. Sente-se ditoso quando vê bem-sucedidos os seus esforços, o que representa, para ele, um triunfo, como triunfo é, para um preceptor, os bons êxitos do seu educando." a) — É responsável pelo mau resultado de seus esforços? "Não, pois que fez o que de si dependia.', 'rascunho'),
  (503, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Sofre o Espírito protetor quando vê que seu protegido segue mau caminho, não obstante os avisos que dele recebe? Não há aí uma causa de turbação da sua felicidade?', 'Compungem-no os erros do seu protegido, a quem lastima. Tal aflição, porém, não tem analogia com as angústias da paternidade terrena, porque ele sabe que há remédio para o mal e que o que não se faz hoje, amanhã se fará.', 'rascunho'),
  (504, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Poderemos sempre saber o nome do Espírito nosso protetor, ou anjo-de- guarda?', 'Como quereis saber nomes para vós inexistentes? Supondes que Espíritos só há os que conheceis?" a) — Como então o podemos invocar, se o não conhecemos? "Dai-lhe o nome que quiserdes, o de Espírito superior que vos inspire simpatia ou veneração. O vosso protetor acudirá ao apelo que com esse nome lhe dirigirdes, visto que todos os bons Espíritos são irmãos e se assistem mutuamente.', 'rascunho'),
  (505, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Os protetores, que dão nomes conhecidos, sempre são, realmente, os Espíritos das personalidades que tiveram esses nomes? 180 – Allan Kar dec', 'Não. Muitas vezes, os que os dão são Espíritos simpáticos aos que de tais nomes usaram na Terra e, a mando destes, respondem ao vosso chamamento. Fazeis questão de nomes; eles tomam um que vos inspire confiança. Quando não podeis desempenhar pessoalmente determinada missão, não costumais mandar que outro, por quem respondeis como por vós mesmos, obre em vosso nome?', 'rascunho'),
  (506, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Na vida espírita, reconheceremos o Espírito nosso protetor?', 'Decerto, pois não é raro que o tenhais conhecido antes de encarnardes.', 'rascunho'),
  (507, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Pertencem todos os Espíritos protetores à classe dos Espíritos elevados? Podem contar-se entre os de classe média? Um pai, por exemplo, pode tornar-se o Espírito protetor de seu filho?', 'Pode, mas a proteção pressupõe certo grau de elevação e um poder ou uma virtude a mais, concedidos por Deus. O pai, que protege seu filho, também pode ser assistido por um Espírito mais elevado.', 'rascunho'),
  (508, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Os Espíritos que se achavam em boas condições ao deixarem a Terra, sempre podem proteger os que lhes são caros e que lhes sobrevivem?', 'Mais ou menos restrito é o poder de que desfrutam. A situação em que se encontram nem sempre lhes permite inteira liberdade de ação.', 'rascunho'),
  (509, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Quando em estado de selvageria ou de inferioridade moral, têm os homens, igualmente, seus Espíritos protetores? E, assim sendo, esses Espíritos são de ordem tão elevada quanto a dos Espíritos protetores de homens muito adiantados?', 'Todo homem tem um Espírito que por ele vela, mas as missões são relativas ao fim que visam. Não dais a uma criança, que está aprendendo a ler, um professor de filosofia. O progresso do Espírito familiar guarda relação com o do Espírito protegido. Tendo um Espírito que vela por vós, podeis tornar-vos, a vosso turno, o protetor de outro que vos seja inferior e os progressos que este realize, com o auxílio que lhe dispensardes, contribuirão para o vosso adiantamento. Deus não exige do Espírito mais do que comportem a sua natureza e o grau de elevação a que já chegou.', 'rascunho'),
  (510, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Quando o pai, que vela pelo filho, reencarna, continua a velar por ele?', 'Isso é mais difícil. Contudo, de certo modo o faz, pedindo, num instante de desprendimento, a um Espírito simpático que o assista nessa missão. Demais, os Espíritos só aceitam missões que possam desempenhar até ao fim." "Encarnado, mormente em mundo onde a existência é material, o Espírito se acha muito sujeito ao corpo para poder dedicar-se inteiramente a outro Espírito, isto é, para poder assisti-lo pessoalmente. Tanto assim que os que ainda se não elevaram bastante são também assistidos por outros, que lhes estão acima, de tal sorte que, se por qualquer circunstância um vem a faltar, outro lhe supre a falta.', 'rascunho'),
  (511, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'A cada indivíduo achar-se-á ligado, além do Espírito protetor, um mau Espírito, com o fim de impeli-lo ao erro e de lhe proporcionar ocasiões de lutar entre o bem e o mal?', 'Ligado, não é o termo. É certo que os maus Espíritos procuram desviar do bom caminho o homem, quando se lhes depara ocasião. Sempre, porém, que um deles se liga a um indivíduo, fá-lo por si mesmo, porque conta ser atendido. Há então luta entre o bom e o mau, vencendo aquele por quem o homem se deixe influenciar.', 'rascunho'),
  (512, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Podemos ter muitos Espíritos protetores?', 'Todo homem conta sempre Espíritos, mais ou menos elevados, que com ele simpatizam, que lhe dedicam afeto e por ele se interessam, como também tem junto de si outros que o assistem no mal.', 'rascunho'),
  (513, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Os Espíritos que conosco simpatizam atuam em cumprimento de missão?', 'Não raro, desempenham missão temporária; porém, as mais das vezes, são apenas atraídos pela identidade de pensamentos e sentimentos, assim para o bem como para o mal." a) — Parece lícito inferir-se daí que os Espíritos a quem somos simpáticos podem ser bons ou maus, não? "Sim, qualquer que seja o seu caráter, o homem sempre encontra Espíritos que com ele simpatizem.', 'rascunho'),
  (514, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Os Espíritos familiares são os mesmos a quem chamamos Espíritos simpáticos ou Espíritos protetores?', 'Há gradações na proteção e na simpatia. Dai-lhes os nomes que quiserdes. O Espírito familiar é antes o amigo da casa." Das explicações acima e das observações feitas sobre a natureza dos Espíritos que se afeiçoam ao homem, pode-se deduzir o seguinte: O Espírito protetor, anjo de guarda, ou bom gênio é o que tem por missão acompanhar o homem na vida e ajudá-lo a progredir. É sempre de natureza superior, com relação ao protegido. Os Espíritos familiares se ligam a certas pessoas por laços mais ou menos duráveis, com o fim de lhes serem úteis, dentro dos limites do poder, quase sempre muito restrito, de que dispõem. São bons, porém muitas vezes pouco adiantados e mesmo um tanto levianos. Ocupam-se de boa mente com as particularidades da vida íntima e só atuam por ordem ou com permissão dos Espíritos protetores. Os Espíritos simpáticos são os que se sentem atraídos para o nosso lado por afeições particulares e ainda por uma certa semelhança de gostos e de sentimentos, tanto para o bem como para o mal. De ordinário, a duração de suas relações se acha subordinada às circunstâncias. O mau gênio é um Espírito imperfeito ou perverso, que se liga ao homem para desviá-lo do bem. Obra, porém, por impulso próprio e não no desempenho de missão. A tenacidade da sua ação está em relação direta com a maior ou menor facilidade de acesso que encontre por parte do homem, que goza sempre da liberdade de escutar-lhe a voz ou de lhe cerrar os ouvidos.', 'rascunho'),
  (515, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Que se há de pensar dessas pessoas que se ligam a certos indivíduos para levá- los à perdição, ou para guiá-los pelo bom caminho? 182 – Allan Kar dec', 'Efetivamente, certas pessoas exercem sobre outras uma espécie de fascinação que parece irresistível. Quando isso se dá no sentido do mal, são maus Espíritos, de que outros Espíritos também maus se servem para subjugá-las. Deus permite que tal coisa ocorra para vos experimentar.', 'rascunho'),
  (516, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Poderiam os nossos bom e mau gênios encarnar, a fim de mais de perto nos acompanharem na vida?', 'Isso às vezes se dá. Porém, o que mais freqüentemente se verifica é encarregarem dessa missão outros Espíritos encarnados que lhes são simpáticos.', 'rascunho'),
  (517, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Haverá Espíritos que se liguem a uma família inteira para protegê-la?', 'Alguns Espíritos se ligam aos membros de uma determinada família, que vivem juntos e unidos pela afeição; mas, não acrediteis em Espíritos protetores do orgulho das raças.', 'rascunho'),
  (518, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Assim como são atraídos, pela simpatia, para certos indivíduos, são-no igualmente os Espíritos, por motivos particulares, para as reuniões de indivíduos?', 'Os Espíritos preferem estar no meio dos que se lhes assemelham. Acham- se aí mais à vontade e mais certos de serem ouvidos. É pelas suas tendências que o homem atrai os Espíritos e isso quer esteja só, quer faça parte de um todo coletivo, como uma sociedade, uma cidade, ou um povo. Portanto, as sociedades, as cidades e os povos são, de acordo com as paixões e o caráter neles predominantes, assistidos por Espíritos mais ou menos elevados. Os Espíritos imperfeitos se afastam dos que os repelem. Segue-se que o aperfeiçoamento moral das coletividades, como o dos indivíduos, tende a afastar os maus Espíritos e a atrair os bons, que estimulam e alimentam nelas o sentimento do bem, como outros lhes podem insuflar as paixões grosseiras.', 'rascunho'),
  (519, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'As aglomerações de indivíduos, como as sociedades, as cidades, as nações, têm Espíritos protetores especiais?', 'Têm, pela razão de que esses agregados são individualidades coletivas que, caminhando para um objetivo comum, precisam de uma direção superior.', 'rascunho'),
  (520, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Os Espíritos protetores das coletividades são de natureza mais elevada do que os que se ligam aos indivíduos?', 'Tudo é relativo ao grau de adiantamento, quer se trate de coletividades, quer de indivíduos.', 'rascunho'),
  (521, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Podem certos Espíritos auxiliar o progresso das artes, protegendo os que às artes se dedicam?', 'Há Espíritos protetores especiais e que assistem os que os invocam, quando dignos dessa assistência. Que queres, porém, que façam com os que julgam ser o que não são? Não lhes cabe fazer que os cegos vejam, nem que os surdos ouçam." Os antigos fizeram, desses Espíritos, divindades especiais. As Musas não eram senão a personificação alegórica dos Espíritos protetores das ciências e das artes, como os deuses Lares e Penates simbolizavam os Espíritos protetores da família. Também modernamente, as artes, as diferentes indústrias, as cidades, os países têm seus patronos, que mais não são do que Espíritos superiores, sob várias designações. Tendo todo homem Espíritos que com ele simpatizam, claro é que, nos corpos coletivos, a generalidade dos Espíritos que lhes votam simpatia está em proporção com a generalidade dos indivíduos; que os Espíritos estranhos são atraídos para essas coletividades pela identidade dos gostos e das idéias; em suma, que esses agregados de pessoas, tanto quanto os indivíduos, são mais ou menos bem assistidos e influenciados, de acordo com a natureza dos sentimentos dominantes entre os elementos que os compõem. Nos povos, determinam a atração dos Espíritos os costumes, os hábitos, o caráter dominante e as leis, as leis sobretudo, porque o caráter de uma nação se reflete nas suas leis. Fazendo reinar em seu seio a justiça, os homens combatem a influência dos maus Espíritos. Onde quer que as leis consagrem coisas injustas, contrárias à Humanidade, os bons Espíritos ficam em minoria e a multidão, que aflui, dos maus mantém a nação aferrada às suas idéias e paralisa as boas influências parciais, que ficam perdidas no conjunto, como insuladas espigas entre espinheiros. Estudando-se os costumes dos povos ou de qualquer reunião de homens, facilmente se forma idéia da população oculta que se lhes imiscui no modo de pensar e nos atos.', 'rascunho'),
  (522, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'O pressentimento é sempre um aviso do Espírito protetor?', 'É o conselho íntimo e oculto de um Espírito que vos quer bem. Também está na intuição da escolha que se haja feito. É a voz do instinto. Antes de encarnar, tem o Espírito conhecimento das fases principais de sua existência, isto é, do gênero das provas a que se submete. Tendo estas caráter assinalado, ele conserva, no seu foro íntimo, uma espécie de impressão de tais provas e esta impressão, que é a voz do instinto, fazendo-se ouvir quando lhe chega o momento de sofrê-las, se torna pressentimento.', 'rascunho'),
  (523, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Acontecendo que os pressentimentos e a voz do instinto são sempre algum tanto vagos, que devemos fazer, na incerteza em que ficamos?', 'Quando te achares na incerteza, invoca o teu bom Espírito, ou ora a Deus, soberano senhor de todos, e ele te enviará um de seus mensageiros, um de nós.', 'rascunho'),
  (524, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Os avisos dos Espíritos protetores objetivam unicamente o nosso procedimento moral, ou também o proceder que devamos adotar nos assuntos da vida particular?', 'Tudo. Eles se esforçam para que vivais o melhor possível. Mas, quase sempre tapais os ouvidos aos avisos salutares e vos tornais desgraçados por culpa vossa." Os Espíritos protetores nos ajudam com seus conselhos, mediante a voz da consciência que fazem ressoar em nosso íntimo. Como, porém, nem sempre ligamos a isso a devida importância, outros conselhos mais diretos eles nos dão, servindo-se das pessoas que nos cercam. Examine cada um as diversas circunstâncias felizes ou infelizes de sua vida e verá que em muitas ocasiões recebeu conselhos de que se não aproveitou e que lhe teriam poupado muitos desgostos, se os houvera escutado. 184 – Allan Kar dec', 'rascunho'),
  (525, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Exercem os Espíritos alguma influência nos acontecimentos da vida?', 'Certamente, pois que vos aconselham." a) — Exercem essa influência por outra forma que não apenas pelos pensamentos que sugerem, isto é, têm ação direta sobre o cumprimento das coisas? "Sim, mas nunca atuam fora das leis da Natureza." Imaginamos erradamente que aos Espíritos só caiba manifestar sua ação por fenômenos extraordinários. Quiséramos que nos viessem auxiliar por meio de milagres e os figuramos sempre armados de uma varinha mágica. Por não ser assim é que oculta nos parece a intervenção que têm nas coisas deste mundo e muito natural o que se executa com o concurso deles. Assim é que, provocando, por exemplo, o encontro de duas pessoas, que suporão encontrar-se por acaso; inspirando a alguém a idéia de passar por determinado lugar; chamando-lhe a atenção para certo ponto, se disso resulta o que tenham em vista, eles obram de tal maneira que o homem, crente de que obedece a um impulso próprio, conserva sempre o seu livre-arbítrio.', 'rascunho'),
  (526, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Tendo, como têm, ação sobre a matéria, podem os Espíritos provocar certos efeitos, com o objetivo de que se dê um acontecimento? Por exemplo: um homem tem que morrer; sobe uma escada, a escada se quebra e ele morre da queda. Foram os Espíritos que quebraram a escada, para que o destino daquele homem se cumprisse?', 'É exato que os Espíritos têm ação sobre a matéria, mas para cumprimento das leis da Natureza, não para as derrogar, fazendo que, em dado momento, ocorra um sucesso inesperado e em contrário àquelas leis. No exemplo que figuraste, a escada se quebrou porque se achava podre, ou por não ser bastante forte para suportar o peso de um homem. Se era destino daquele homem perecer de tal maneira, os Espíritos lhe inspirariam a idéia de subir a escada em questão, que teria de quebrar-se com o seu peso, resultando-lhe daí a morte por um efeito natural e sem que para isso fosse mister a produção de um milagre.', 'rascunho'),
  (527, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Tomemos outro exemplo, em que não entre a matéria em seu estado natural. Um homem tem que morrer fulminado pelo raio. Refugia-se debaixo de uma árvore. Estala o raio e o mata. Poderá dar-se tenham sido os Espíritos que provocaram a produção do raio e que o dirigiram para o homem?', 'Dá-se o mesmo que anteriormente. O raio caiu sobre aquela árvore em tal momento, porque estava nas leis da Natureza que assim acontecesse. Não foi encaminhado para a árvore, por se achar debaixo dela o homem. A este, sim, foi inspirada a idéia de se abrigar debaixo de uma árvore sobre a qual cairia o raio, porquanto a árvore não deixaria de ser atingida, só por não lhe estar debaixo da fronde o homem.', 'rascunho'),
  (528, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'No caso de uma pessoa mal-intencionada disparar sobre outra um projétil que apenas lhe passe perto sem a atingir, poderá ter sucedido que um Espírito bondoso haja desviado o projétil?', 'Se o indivíduo alvejado não tem que perecer desse modo, o Espírito bondoso lhe inspirará a idéia de se desviar, ou então poderá ofuscar o que empunha a arma, de sorte a fazê-lo apontar mal, porquanto, uma vez disparada a arma, o projétil segue a linha que tem de percorrer.', 'rascunho'),
  (529, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Que se deve pensar das balas encantadas, de que falam algumas lendas e que fatalmente atingem o alvo?', 'Pura imaginação. O homem gosta do maravilhoso e não se contenta com as maravilhas da Natureza." a) — Podem os Espíritos que dirigem os acontecimentos terrenos ter obstada sua ação por Espíritos que queiram o contrário? "O que Deus quer se executa. Se houver demora na execução, ou lhe surjam obstáculos, é porque ele assim o quis.', 'rascunho'),
  (530, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Não podem os Espíritos levianos e zombeteiros criar pequenos embaraços à realização dos nossos projetos e transtornar as nossas previsões? Serão eles, numa palavra, os causadores do que chamamos pequenas misérias da vida humana?', 'Eles se comprazem em vos causar aborrecimentos que representam para vós provas destinadas a exercitar a vossa paciência. Cansam-se, porém, quando vêem que nada conseguem. Entretanto, não seria justo, nem acertado, imputar-lhes todas as decepções que experimentais e de que sois os principais culpados pela vossa irreflexão. Fica certo de que, se a tua louça se quebra, é mais por desazo teu do que por culpa dos Espíritos." a) — Destes, os que provocam contrariedades obram impelidos por animosidade pessoal, ou assim procedem contra qualquer, sem motivo determinado, por pura malícia? " Por uma e outra coisa. Às vezes os que assim vos molestam são inimigos que granjeastes nesta ou em precedente existência. Doutras vezes, nenhum motivo há.', 'rascunho'),
  (531, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Extingue-se-lhes com a vida corpórea a malevolência dos seres que nos fizeram mal na Terra?', 'Muitas vezes reconhecem a injustiça com que procederam e o mal que causaram. Mas, também, não é raro que continuem a perseguir-vos, cheios de animosidade, se Deus o permitir, por ainda vos experimentar." a) — Pode-se pôr termo a isso? Por que meio? "Podeis. Orando por eles e lhes retribuindo o mal com o bem, acabarão compreendendo a injustiça do proceder deles. Demais, se souberdes colocar-vos acima de suas maquinações, deixar-vos-ão, por verificarem que nada lucram." A experiência demonstra que alguns Espíritos continuam em outra existência a exercer as vinganças que vinham tomando e que assim, cedo ou tarde, o homem paga o mal que tenha feito a outrem. 186 – Allan Kar dec', 'rascunho'),
  (532, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Têm os Espíritos o poder de afastar de certas pessoas os males e de favorecê- las com a prosperidade?', 'De todo, não; porquanto, há males que estão nos decretos da Providência. Amenizam-vos, porém, as dores, dando-vos paciência e resignação." "Ficai igualmente sabendo que de vós depende muitas vezes poupar-vos aos males, ou, quando menos, atenuá-los. A inteligência, Deus vo-la outorgou para que dela vos sirvais e é principalmente por meio da vossa inteligência que os Espíritos vos auxiliam, sugerindo-vos idéias propícias ao vosso bem. Mas, não assistem senão os que sabem assistir-se a si mesmos. Esse o sentido destas palavras: Buscai e achareis, batei e se vos abrirá." "Sabei ainda que nem sempre é um mal o que vos parece sê-lo. Freqüentemente, do que considerais um mal sairá um bem muito maior. Quase nunca compreendeis isso, porque só atentais no momento presente ou na vossa própria pessoa.', 'rascunho'),
  (533, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Podem os Espíritos fazer que obtenham riquezas os que lhes pedem que assim aconteça?', 'Algumas vezes, como prova. Quase sempre, porém, recusam, como se recusa à criança a satisfação de um pedido inconsiderado." a) — São os bons ou os maus Espíritos que concedem esses favores? "Uns e outros. Depende da intenção. As mais das vezes, entretanto, os que os concedem são os Espíritos que vos querem arrastar para o mal e que encontram meio fácil de o conseguirem, facilitando-vos os gozos que a riqueza proporciona.', 'rascunho'),
  (534, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Será por influência de algum Espírito que, fatalmente, a realização dos nossos projetos parece encontrar obstáculos?', 'Algumas vezes é isso efeito da ação dos Espíritos; muito mais vezes, porém, é que andais errados na elaboração e na execução dos vossos projetos. Muito influem nesses casos a posição e o caráter do indivíduo. Se vos obstinais em ir por um caminho que não deveis seguir, os Espíritos nenhuma culpa têm dos vossos insucessos. Vós mesmos vos constituís em vossos maus gênios.', 'rascunho'),
  (535, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Quando algo de venturoso nos sucede é ao Espírito nosso protetor que devemos agradecê-lo?', 'Agradecei primeiramente a Deus, sem cuja permissão nada se faz; depois, aos bons Espíritos que foram os agentes da sua vontade." a) — Que sucederia se nos esquecêssemos de agradecer? "O que sucede aos ingratos." b) — No entanto, pessoas há que não pedem nem agradecem e às quais tudo sai bem! "Assim é, de fato, mas importa ver o fim. Pagarão bem caro essa felicidade de que não são merecedoras, pois quanto mais houverem recebido, tanto maiores contas terão que prestar.', 'rascunho'),
  (536, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'São devidos a causas fortuitas, ou, ao contrário, têm todos um fim providencial, os grandes fenômenos da Natureza, os que se consideram como perturbação dos elementos?', 'Tudo tem uma razão de ser e nada acontece sem a permissão de Deus." a) — Objetivam sempre o homem esses fenômenos? "Às vezes têm, como imediata razão de ser, o homem. Na maioria dos casos, entretanto, têm por único motivo o restabelecimento do equilíbrio e da harmonia das forças físicas da Natureza." b) — Concebemos perfeitamente que a vontade de Deus seja a causa primária, nisto como em tudo; porém, sabendo que os Espíritos exercem ação sobre a matéria e que são os agentes da vontade de Deus, perguntamos se alguns dentre eles não exercerão certa influência sobre os elementos para os agitar, acalmar ou dirigir? "Mas, evidentemente. Nem poderia ser de outro modo. Deus não exerce ação direta sobre a matéria. Ele encontra agentes dedicados em todos os graus da escala dos mundos.', 'rascunho'),
  (537, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'A mitologia dos antigos se fundava inteiramente em idéias espíritas, com a única diferença de que consideravam os Espíritos como divindades. Representavam esses deuses ou esses Espíritos com atribuições especiais. Assim, uns eram encarregados dos ventos, outros do raio, outros de presidir ao fenômeno da vegetação, etc. Semelhante crença é totalmente destituída de fundamento?', 'Tão pouco destituída é de fundamento, que ainda está muito aquém da verdade." a) — Poderá então haver Espíritos que habitem o interior da Terra e presidam aos fenômenos geológicos? "Tais Espíritos não habitam positivamente a Terra. Presidem aos fenômenos e os dirigem de acordo com as atribuições que têm. Dia virá em que recebereis a explicação de todos esses fenômenos e os compreendereis melhor.', 'rascunho'),
  (538, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Formam categoria especial no mundo espírita os Espíritos que presidem aos fenômenos da Natureza? Serão seres à parte, ou Espíritos que foram encarnados como nós?', 'Que foram ou que o serão." a) — Pertencem esses Espíritos às ordens superiores ou às inferiores da hierarquia espírita? "Isso é conforme seja mais ou menos material, mais ou menos inteligente o papel que desempenhem. Uns mandam, outros executam. Os que executam coisas materiais são sempre de ordem inferior, assim entre os Espíritos, como entre os homens." 188 – Allan Kar dec', 'rascunho'),
  (539, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'A produção de certos fenômenos, das tempestades, por exemplo, é obra de um só Espírito, ou muitos se reúnem, formando grandes massas, para produzi-los?', 'Reúnem-se em massas inumeráveis.', 'rascunho'),
  (540, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Os Espíritos que exercem ação nos fenômenos da Natureza operam com conhecimento de causa, usando do livre-arbítrio, ou por efeito de instintivo ou irrefletido impulso?', 'Uns sim, outros não. Estabeleçamos uma comparação. Considera essas miríades de animais que, pouco a pouco, fazem emergir do mar ilhas e arquipélagos. Julgas que não há aí um fim providencial e que essa transformação da superfície do globo não seja necessária à harmonia geral? Entretanto, são animais de ínfima ordem que executam essas obras, provendo às suas necessidades e sem suspeitarem de que são instrumentos de Deus. Pois bem, do mesmo modo, os Espíritos mais atrasados oferecem utilidade ao conjunto. Enquanto se ensaiam para a vida, antes que tenham plena consciência de seus atos e estejam no gozo pleno do livre-arbítrio, atuam em certos fenômenos, de que inconscientemente se constituem os agentes. Primeiramente, executam. Mais tarde, quando suas inteligências já houverem alcançado um certo desenvolvimento, ordenarão e dirigirão as coisas do mundo material. Depois, poderão dirigir as do mundo moral. É assim que tudo serve, que tudo se encadeia na Natureza, desde o átomo primitivo até o arcanjo, que também começou por ser átomo. Admirável lei de harmonia, que o vosso acanhado espírito ainda não pode apreender em seu conjunto!', 'rascunho'),
  (541, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Durante uma batalha, há Espíritos assistindo e amparando cada um dos exércitos?', 'Sim, e que lhes estimulam a coragem." Os antigos figuravam os deuses tomando o partido deste ou daquele povo. Esses deuses eram simplesmente Espíritos representados por alegorias.', 'rascunho'),
  (542, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Estando, numa guerra, a justiça sempre de um dos lados, como pode haver Espíritos que tomem o partido dos que se batem por uma causa injusta?', 'Bem sabeis haver Espíritos que só se comprazem na discórdia e na destruição. Para esses, a guerra é a guerra. A justiça da causa pouco os preocupa.', 'rascunho'),
  (543, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Podem alguns Espíritos influenciar o general na concepção de seus planos de campanha?', 'Sem dúvida alguma. Podem influenciá-lo nesse sentido, como com relação a todas as concepções.', 'rascunho'),
  (544, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Poderiam maus Espíritos suscitar-lhe planos errôneos com o fim de levá-lo à derrota?', 'Podem; mas, não tem ele o livre-arbítrio? Se não tiver critério bastante para distinguir uma idéia falsa, sofrerá as conseqüências e melhor faria se obedecesse, em vez de comandar.', 'rascunho'),
  (545, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Pode, alguma vez, o general ser guiado por uma espécie de dupla vista, por uma visão intuitiva, que lhe mostre de antemão o resultado de seus planos?', 'Isso se dá amiúde com o homem de gênio. É o que ele chama inspiração e o que faz que obre com uma espécie de certeza. Essa inspiração lhe vem dos Espíritos que o dirigem, os quais se aproveitam das faculdades de que o vêem dotado.', 'rascunho'),
  (546, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'No tumulto dos combates, que se passa com os Espíritos dos que sucumbem? Continuam, após a morte, a interessar-se pela batalha?', 'Alguns continuam a interessar-se, outros se afastam." Dá-se, nos combates, o que ocorre em todos os casos de morte violenta: no primeiro momento, o Espírito fica surpreendido e como que atordoado. Julga não estar morto. Parece-lhe que ainda toma parte na ação. Só pouco a pouco a realidade lhe surge.', 'rascunho'),
  (547, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Após a morte, os Espíritos, que como vivos se guerreavam, continuam a considerar-se inimigos e se conservam encarniçados uns contra os outros?', 'Nessas ocasiões, o Espírito nunca está calmo. Pode acontecer que nos primeiros instantes depois da morte ainda odeie o seu inimigo e mesmo o persiga. Quando, porém, se lhe restabelece a serenidade nas idéias, vê que nenhum fundamento há mais para sua animosidade. Contudo, não é impossível que dela guarde vestígios mais ou menos fortes, conforme o seu caráter." a) — Continua a ouvir o rumor da batalha? "Perfeitamente.', 'rascunho'),
  (548, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'O Espírito que, como espectador, assiste calmamente a um combate observa o ato de separar-se a alma do corpo? Como é que esse fenômeno se lhe apresenta à observação?', 'Raras são as mortes verdadeiramente instantâneas. Na maioria dos casos, o Espírito, cujo corpo acaba de ser mortalmente ferido, não tem consciência imediata desse fato. Somente quando ele começa a reconhecer a nova condição em que se acha, é que os assistentes podem distingui-lo, a mover-se ao lado do cadáver. Parece isso tão natural, que nenhum efeito desagradável lhe causa a vista do corpo morto. Tendo-se a vida toda concentrado no Espírito, só ele prende a atenção dos outros. É com ele que estes conversam, ou a ele é que fazem determinações.', 'rascunho'),
  (549, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Algo de verdade haverá nos pactos com os maus Espíritos?', 'Não, não há pactos. Há, porém, naturezas más que simpatizam com os maus Espíritos. Por exemplo: queres atormentar o teu vizinho e não sabes como hás de fazer. Chamas então por Espíritos inferiores que, como tu, só querem o mal e que, para te ajudarem, exigem que também os sirvas em seus maus desígnios. Mas, não se segue que o teu vizinho não possa livrar-se deles por meio de uma conjuração oposta e pela ação da sua vontade. Aquele que intenta praticar uma ação má, pelo 190 – Allan Kar dec simples fato de alimentar essa intenção, chama em seu auxílio maus Espíritos, aos quais fica então obrigado a servir, porque dele também precisam esses Espíritos, para o mal que queiram fazer. Nisto apenas é que consiste o pacto." O fato de o homem ficar, às vezes, na dependência dos Espíritos inferiores nasce de se entregar aos maus pensamentos que estes lhe sugerem e não de estipulações quaisquer que com eles faça. O pacto, no sentido vulgar do termo, é uma alegoria representativa da simpatia existente entre um indivíduo de natureza má e Espíritos malfazejos.', 'rascunho'),
  (550, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Qual o sentido das lendas fantásticas em que figuram indivíduos que teriam vendido suas almas a Satanás para obterem certos favores?', 'Todas as fábulas encerram um ensinamento e um sentido moral. O vosso erro consiste em tomá-las ao pé da letra. Isso a que te referes é uma alegoria, que se pode explicar desta maneira: aquele que chama em seu auxílio os Espíritos, para deles obter riquezas, ou qualquer outro favor, rebela-se contra a Providência; renuncia à missão que recebeu e às provas que lhe cumpre suportar neste mundo. Sofrerá na vida futura as conseqüências desse ato. Não quer isto dizer que sua alma fique para sempre condenada à desgraça. Mas, desde que, em lugar de se desprender da matéria, nela cada vez se enterra mais, não terá, no mundo dos Espíritos, a satisfação de que haja gozado na Terra, até que tenha resgatado a sua falta, por meio de novas provas, talvez maiores e mais penosas. Coloca-se, por amor dos gozos materiais, na dependência dos Espíritos impuros. Estabelece-se assim, tacitamente, entre estes e o delinqüente, um pacto que o leva à sua perda, mas que lhe será sempre fácil romper, se o quiser firmemente, granjeando a assistência dos bons Espíritos.', 'rascunho'),
  (551, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Pode um homem mau, com o auxílio de um mau Espírito que lhe seja dedicado, fazer mal ao seu próximo?', 'Não; Deus não o permitiria.', 'rascunho'),
  (552, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Que se deve pensar da crença no poder, que certas pessoas teriam, de enfeitiçar?', 'Algumas pessoas dispõem de grande força magnética, de que podem fazer mau uso, se maus forem seus próprios Espíritos, caso em que possível se torna serem secundados por outros Espíritos maus. Não creias, porém, num pretenso poder mágico, que só existe na imaginação de criaturas supersticiosas, ignorantes das verdadeiras leis da Natureza. Os fatos que citam, como prova da existência desse poder, são fatos naturais, mal observados e sobretudo mal compreendidos.', 'rascunho'),
  (553, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Que efeito podem produzir as fórmulas e práticas mediante as quais pessoas há que pretendem dispor do concurso dos Espíritos?', 'O efeito de torná-las ridículas, se procedem de boa-fé. No caso contrário, são tratantes que merecem castigo. Todas as fórmulas são mera charlatanearia. Não há palavra sacramental nenhuma, nenhum sinal cabalístico, nem talismã, que tenha qualquer ação sobre os Espíritos, porquanto estes só são atraídos pelo pensamento e não pelas coisas materiais." a) — Mas, não é exato que alguns Espíritos têm ditado, eles próprios, fórmulas cabalísticas? "Efetivamente, Espíritos há que indicam sinais, palavras estranhas, ou prescrevem a prática de atos, por meio dos quais se fazem os chamados conjuros. Mas, ficai certos de que são Espíritos que de vós outros escarnecem e zombam da vossa credulidade.', 'rascunho'),
  (554, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Não pode aquele que, com ou sem razão, confia no que chama a virtude de um talismã, atrair um Espírito, por efeito mesmo dessa confiança, visto que, então, o que atua é o pensamento, não passando o talismã de um sinal que apenas lhe auxilia a concentração?', 'É verdade; mas, da pureza da intenção e da elevação dos sentimentos depende a natureza do Espírito que é atraído. Ora, muito raramente aquele que seja bastante simplório para acreditar na virtude de um talismã deixará de colimar um fim mais material do que moral. Qualquer, porém, que seja o caso, essa crença denuncia uma inferioridade e uma fraqueza de idéias que favorecem a ação dos Espíritos imperfeitos e escarninhos.', 'rascunho'),
  (555, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Que sentido se deve dar ao qualificativo de feiticeiro?', 'Aqueles a quem chamais feiticeiros são pessoas que, quando de boa-fé, gozam de certas faculdades, como sejam a força magnética ou a dupla vista. Então, como fazem coisas geralmente incompreensíveis, são tidas por dotadas de um poder sobrenatural. Os vossos sábios não têm passado muitas vezes por feiticeiros aos olhos dos ignorantes?" O Espiritismo e o magnetismo nos dão a chave de uma imensidade de fenômenos sobre os quais a ignorância teceu um sem-número de fábulas, em que os fatos se apresentam exagerados pela imaginação. O conhecimento lúcido dessas duas ciências que, a bem dizer, formam uma única, mostrando a realidade das coisas e suas verdadeiras causas, constitui o melhor preservativo contra as idéias supersticiosas, porque revela o que é possível e o que é impossível, o que está nas leis da Natureza e o que não passa de ridícula crendice.', 'rascunho'),
  (556, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Têm algumas pessoas, verdadeiramente, o poder de curar pelo simples contacto?', 'A força magnética pode chegar até aí, quando secundada pela pureza dos sentimentos e por um ardente desejo de fazer o bem, porque então os bons Espíritos lhe vêm em auxílio. Cumpre, porém, desconfiar da maneira pela qual contam as coisas pessoas muito crédulas e muito entusiastas, sempre dispostas a considerar maravilhoso o que há de mais simples e mais natural. Importa desconfiar também das narrativas interesseiras, que costumam fazer os que exploram, em seu proveito, a credulidade alheia." 192 – Allan Kar dec', 'rascunho'),
  (557, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo IX — Da intervenção dos Espíritos no mundo corporal', 'Podem a bênção e a maldição atrair o bem e o mal para aquele sobre quem são lançadas?', 'Deus não escuta a maldição injusta e culpado perante ele se torna o que a profere. Como temos os dois gênios opostos, o bem e o mal, pode a maldição exercer momentaneamente influência, mesmo sobre a matéria. Tal influência, porém, só se verifica por vontade de Deus como aumento de prova para aquele que é dela objeto. Demais, o que é comum é serem amaldiçoados os maus e abençoados os bons. Jamais a bênção e a maldição podem desviar da senda da justiça a Providência, que nunca fere o maldito, senão quando mau, e cuja proteção não acoberta senão aquele que a merece.', 'rascunho'),
  (558, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Alguma outra coisa incumbe aos Espíritos fazer, que não seja melhorarem-se pessoalmente?', 'Concorrem para a harmonia do Universo, executando as vontades de Deus, cujos ministros eles são. A vida espírita é uma ocupação contínua, mas que nada tem de penosa, como a vida na Terra, porque não há a fadiga corporal, nem as angústias das necessidades.', 'rascunho'),
  (559, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Também desempenham função útil no Universo os Espíritos inferiores e imperfeitos?', 'Todos têm deveres a cumprir. Para a construção de um edifício, não concorre tanto o último dos serventes de pedreiro, como o arquiteto?', 'rascunho'),
  (560, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Tem atribuições especiais cada Espírito?', 'Todos temos que habitar em toda parte e adquirir o conhecimento de todas as coisas, presidindo sucessivamente ao que se efetua em todos os pontos do Universo. Mas, como diz o Eclesiastes, há tempo para tudo. Assim, tal Espírito cumpre hoje neste mundo o seu destino, tal outro cumprirá ou já cumpriu o seu, em época diversa, na terra, na água, no ar, etc.', 'rascunho'),
  (561, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'São permanentes para cada um e estão nas atribuições exclusivas de certas classes as funções que os Espíritos desempenham na ordem das coisas?', 'Todos têm que percorrer os diferentes graus da escala, para se aperfeiçoarem. Deus, que é justo, não poderia ter dado a uns a ciência sem trabalho, destinando outros a só a adquirirem com esforço." É o que sucede entre os homens, onde ninguém chega ao supremo grau de perfeição numa arte qualquer, sem que tenha adquirido os conhecimentos necessários, praticando os rudimentos dessa arte. 194 – Allan Kar dec', 'rascunho'),
  (562, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Já não tendo o que adquirir, os Espíritos da ordem mais elevada se acham em repouso absoluto, ou também lhes tocam ocupações?', 'Que quererias que fizessem na eternidade? A ociosidade eterna seria um eterno suplício." a) — De que natureza são as suas ocupações? "Receber diretamente as ordens de Deus, transmiti-las ao Universo inteiro e velar por que sejam cumpridas.', 'rascunho'),
  (563, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'São incessantes as ocupações dos Espíritos?', 'Incessantes, sim, atendendo-se a que sempre ativos são os seus pensamentos, porquanto vivem pelo pensamento. Importa, porém, não identifiqueis as ocupações dos Espíritos com as ocupações materiais dos homens. Essa mesma atividade lhes constitui um gozo, pela consciência que têm de ser úteis." a) — Concebe-se isto com relação aos bons Espíritos. Dar-se-á, entretanto, o mesmo com os Espíritos inferiores? "A estes cabem ocupações apropriadas à sua natureza. Confiais, porventura, ao obreiro manual e ao ignorante trabalhos que só o homem instruído pode executar?', 'rascunho'),
  (564, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Haverá Espíritos que se conservem ociosos, que em coisa alguma útil se ocupem?', 'Há, mas esse estado é temporário e dependendo do desenvolvimento de suas inteligências. Há, certamente, como há homens que só para si mesmos vivem. Pesa-lhes, porém, essa ociosidade e, cedo ou tarde, o desejo de progredir lhes faz necessária a atividade e felizes se sentirão por poderem tornar-se úteis. Referimo- nos aos Espíritos que hão chegado ao ponto de terem consciência de si mesmos e do seu livre-arbítrio; porquanto, em sua origem, todos são quais crianças que acabam de nascer e que obram mais por instinto que por vontade expressa.', 'rascunho'),
  (565, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Atentam os Espíritos em nossos trabalhos de arte e por eles se interessam?', 'Atentam no que prove a elevação dos Espíritos e seus progressos.', 'rascunho'),
  (566, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Um Espírito, que haja cultivado na Terra uma especialidade artística, que tenha sido, por exemplo, pintor, ou arquiteto, se interessa de preferência pelos trabalhos que constituíram objeto de sua predileção durante a vida?', 'Tudo se confunde num objetivo geral. Se for um Espírito bom, esses trabalhos o interessarão na medida do ensejo que lhe proporcionem de auxiliar as almas a se elevarem para Deus. Demais, esqueceis que um Espírito que cultivou certa arte, na existência em que o conhecestes, pode ter cultivado outra em anterior existência, pois que lhe cumpre saber tudo para ser perfeito. Assim, conforme o grau do seu adiantamento, pode suceder que nada seja para ele uma especialidade. Foi o que eu quis significar, dizendo que tudo se confunde num objetivo geral. Notai ainda o seguinte: o que, no vosso mundo atrasado, considerais sublime, não passa de infantilidade, comparado ao que há em mundos mais adiantados. Como pretenderíeis que os Espíritos que habitam esses mundos, onde existem artes que desconheceis, admirem o que, aos seus olhos, corresponde a trabalhos de colegiais? Por isso disse eu: atentam no que demonstre progresso." a) — Concebemos que seja assim, em se tratando de Espíritos muito adiantados. Referimo-nos, porém, a Espíritos mais vulgares, que ainda se não elevaram acima das idéias terrenas. "Com relação a esses, o caso é diferente. Mais restrito é o ponto de vista donde observam as coisas. Podem, portanto, admirar o que vos cause admiração.', 'rascunho'),
  (567, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Costumam os Espíritos imiscuir-se em nossos prazeres e ocupações?', 'Os Espíritos vulgares, como dizes, costumam. Esses vos rodeiam constantemente e com freqüência tomam parte muito ativa no que fazeis, de conformidade com suas naturezas. Cumpre assim aconteça, porque, para serem os homens impelidos pelas diversas veredas da vida, necessário é que se lhes excitem ou moderem as paixões." Com as coisas deste mundo os Espíritos se ocupam conformemente ao grau de elevação ou de inferioridade em que se achem. Os Espíritos superiores dispõem, sem dúvida, da faculdade de examiná-las nas suas mínimas particularidades, mas só o fazem na medida em que isso seja útil ao progresso. Unicamente os Espíritos inferiores ligam a essas coisas uma importância relativa às reminiscências que ainda conservam e às idéias materiais que ainda se não extinguiram neles.', 'rascunho'),
  (568, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Os Espíritos, que têm missões a cumprir, as cumprem na erraticidade, ou encarnados?', 'Podem tê-las num e noutro estado. Para certos Espíritos errantes, é uma grande ocupação.', 'rascunho'),
  (569, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Em que consistem as missões de que podem ser encarregados os Espíritos errantes?', 'São tão variadas que impossível fora descrevê-las. Muitas há mesmo que não podeis compreender. Os Espíritos executam as vontades de Deus e não vos é dado penetrar-lhe todos os desígnios." As missões dos Espíritos têm sempre por objeto o bem. Quer como Espíritos, quer como homens, são incumbidos de auxiliar o progresso da Humanidade, dos povos ou dos indivíduos, dentro de um círculo de idéias mais ou menos amplas, mais ou menos especiais e de velar pela execução de determinadas coisas. Alguns desempenham missões mais restritas e, de certo modo, pessoais ou inteiramente locais, como sejam assistir os enfermos, os agonizantes, os aflitos, velar por aqueles de quem se constituíram guias e protetores, dirigi- los, dando-lhes conselhos ou inspirando-lhes bons pensamentos. Pode dizer-se que há tantos gêneros de missões quantas as espécies de interesses a resguardar, assim no mundo físico, como no moral. O Espírito se adianta conforme à maneira por que desempenha a sua tarefa.', 'rascunho'),
  (570, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Os Espíritos percebem sempre os desígnios que lhes compete executar?', 'Não. Muitos há que são instrumentos cegos. Outros, porém, sabem muito bem com que fim atuam." 196 – Allan Kar dec', 'rascunho'),
  (571, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Só os Espíritos elevados desempenham missões?', 'A importância das missões corresponde às capacidades e à elevação do Espírito. O estafeta que leva um telegrama ao seu destinatário também desempenha uma perfeita missão, se bem que diversa da de um general.', 'rascunho'),
  (572, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'A missão de um Espírito lhe é imposta, ou depende da sua vontade?', 'Ele a pede e ditoso se considera se a obtém." a) — Pode uma igual missão ser pedida por muitos Espíritos? "Sim, é freqüente apresentarem-se muitos candidatos, mas nem todos são aceitos.', 'rascunho'),
  (573, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Em que consiste a missão dos Espíritos encarnados?', 'Em instruir os homens, em lhes auxiliar o progresso; em lhes melhorar as instituições, por meios diretos e materiais. As missões, porém, são mais ou menos gerais e importantes. O que cultiva a terra desempenha tão nobre missão, como o que governa, ou o que instrui. Tudo em a Natureza se encadeia. Ao mesmo tempo que o Espírito se depura pela encarnação, concorre, dessa forma, para a execução dos desígnios da Providência. Cada um tem neste mundo a sua missão, porque todos podem ter alguma utilidade.', 'rascunho'),
  (574, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Qual pode ser, na Terra, a missão das criaturas voluntariamente inúteis?', 'Há efetivamente pessoas que só para si mesmas vivem e que não sabem tornar-se úteis ao que quer que seja. São pobres seres dignos de compaixão, porquanto expiarão duramente sua voluntária inutilidade, começando-lhes muitas vezes, já neste mundo, o castigo, pelo aborrecimento e pelo desgosto que a vida lhes causa." a) — Pois que lhes era facultada a escolha, por que preferiram uma existência que nenhum proveito lhes traria? "Entre os Espíritos também há preguiçosos que recuam diante de uma vida de labor. Deus consente que assim procedam. Mais tarde compreenderão, à própria custa, os inconvenientes da inutilidade a que se votaram e serão os primeiros a pedir que se lhes conceda recuperar o tempo perdido. Pode também acontecer que tenham escolhido uma vida útil e que hajam recuado diante da execução da obra, deixando- se levar pelas sugestões dos Espíritos que os induzem a permanecer na ociosidade.', 'rascunho'),
  (575, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'As ocupações comuns mais nos parecem deveres do que missões propriamente ditas. A missão, de acordo com a idéia a que esta palavra está associada, tem um caráter menos exclusivo, de importância sobretudo menos pessoal. Deste ponto de vista, como se pode reconhecer que um homem tem realmente na Terra uma determinada missão?', 'Pelas grandes coisas que opera, pelos progressos a cuja realização conduz seus semelhantes.', 'rascunho'),
  (576, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Foram predestinados a isso, antes de nascerem, os homens que trazem uma importante missão e dela têm conhecimento?', 'Algumas vezes, assim é. Quase sempre, porém, o ignoram. Baixando à Terra, colimam um vago objetivo. Depois do nascimento e de acordo com as circunstâncias é que suas missões se lhes desenham às vistas. Deus os impele para a senda onde devam executar-lhe os desígnios.', 'rascunho'),
  (577, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Quando um homem faz alguma coisa útil fá-la sempre em virtude da missão em que foi anteriormente investido e a que vem predestinado, ou pode suceder que haja recebido missão não prevista?', 'Nem tudo o que o homem faz resulta de missão a que tenha sido predestinado. Amiudadas vezes é o instrumento de que se serve um Espírito para fazer que se execute uma coisa que julga útil. Por exemplo, entende um Espírito ser útil que se escreva um livro, que ele próprio escreveria se estivesse encarnado. Procura então o escritor mais apto a lhe compreender e executar o pensamento. Transmite-lhe a idéia do livro e o dirige na execução. Ora, esse escritor não veio à Terra com a missão de publicar tal obra. O mesmo ocorre com diversos trabalhos artísticos e muitas descobertas. Devemos acrescentar que, durante o sono corporal, o Espírito encarnado se comunica diretamente com o Espírito errante, entendendo-se os dois acerca da execução.', 'rascunho'),
  (578, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Poderá o Espírito, por própria culpa, falir na sua missão?', 'Sim, se não for um Espírito superior." a) — Que conseqüências lhe advirão da sua falência? "Terá que retomar a tarefa; essa a sua punição. Também sofrerá as conseqüências do mal que haja causado.', 'rascunho'),
  (579, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Pois se é de Deus que o Espírito recebe a sua missão, como se há de compreender que Deus confie missão importante e de interesse geral a um Espírito capaz de falir?', 'Não sabe Deus se o seu general obterá a vitória ou se será vencido? Sabe- o, crede, e seus planos, quando importantes, não se apóiam nos que hajam de abandonar em meio a obra. Toda a questão, para vós, está no conhecimento que Deus tem do futuro, mas que não vos é concedido.', 'rascunho'),
  (580, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'O Espírito, que encarna para desempenhar determinada missão, tem apreensões idênticas às de outro que o faz por provação?', 'Não, porque traz a experiência adquirida.', 'rascunho'),
  (581, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Certamente desempenham missão os homens que servem de faróis ao gênero humano, que o iluminam com a luz do gênio. Entre eles, porém, alguns há que se enganam, que, de par com grandes verdades, propagam grandes erros. Como se deve considerar a missão desses homens?', 'Como falseadas por eles próprios. Estão abaixo da tarefa que tomaram sobre os ombros. Contudo, mister se faz levar em conta as circunstâncias. Os homens de gênio têm que falar de acordo com as épocas em que vivem e, assim, um 198 – Allan Kar dec ensinamento que pareceu errôneo ou pueril, numa época adiantada, pode ter sido o que convinha no século em que foi divulgado.', 'rascunho'),
  (582, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'Pode-se considerar como missão a paternidade?', 'É, sem contestação possível, uma verdadeira missão. É ao mesmo tempo grandíssimo dever e que envolve, mais do que o pensa o homem, a sua responsabilidade quanto ao futuro. Deus colocou o filho sob a tutela dos pais, a fim de que estes o dirijam pela senda do bem, e lhes facilitou a tarefa dando àquele uma organização débil e delicada, que o torna propício a todas as impressões. Muitos há, no entanto, que mais cuidam de aprumar as árvores do seu jardim e de fazê-las dar bons frutos em abundância, do que de formar o caráter de seu filho. Se este vier a sucumbir por culpa deles, suportarão os desgostos resultantes dessa queda e partilharão dos sofrimentos do filho na vida futura, por não terem feito o que lhes estava ao alcance para que ele avançasse na estrada do bem.', 'rascunho'),
  (583, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'São responsáveis os pais pelo transviamento de um filho que envereda pelo caminho do mal, apesar dos cuidados que lhe dispensaram?', 'Não; porém, quanto piores forem as propensões do filho, tanto mais pesada é a tarefa e tanto maior o mérito dos pais, se conseguirem desviá-lo do mau caminho." a) — Se um filho se torna homem de bem, não obstante a negligência ou os maus exemplos de seus pais, tiram estes daí algum proveito? "Deus é justo.', 'rascunho'),
  (584, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo X — Das ocupações e missões dos Espíritos', 'De que natureza será a missão do conquistador que apenas visa satisfazer à sua ambição e que, para alcançar esse objetivo, não vacila ante nenhuma das calamidades que vai espalhando?', 'As mais das vezes não passa de um instrumento de que se serve Deus para cumprimento de seus desígnios, representando essas calamidades um meio de que ele se utiliza para fazer que um povo progrida mais rapidamente." a) — Nenhuma parte tendo na produção do bem que dessas calamidades passageiras possa resultar, pois que visava um fim todo pessoal, aquele que delas se constitui instrumento tirará, não obstante, proveito desse bem? "Cada um é recompensado de acordo com as suas obras, com o bem que intentou fazer e com a retidão de suas intenções." Os Espíritos encarnados têm ocupações inerentes às suas existências corpóreas. No estado de erraticidade, ou de desmaterialização, tais ocupações são adequadas ao grau de adiantamento deles. Uns percorrem os mundos, se instruem e preparam para nova encarnação. Outros, mais adiantados, se ocupam com o progresso, dirigindo os acontecimentos e sugerindo idéias que lhe sejam propícias. Assistem os homens de gênio que concorrem para o adiantamento da Humanidade. Outros encarnam com determinada missão de progresso. Outros tomam sob sua tutela os indivíduos, as famílias, as reuniões, as cidades e os povos, dos quais se constituem os anjos guardiães, os gênios protetores e os Espíritos familiares. Outros, finalmente, presidem aos fenômenos da Natureza, de que se fazem os agentes diretos. Os Espíritos vulgares se imiscuem em nossas ocupações e diversões. Os impuros ou imperfeitos aguardam, em sofrimentos e angústias, o momento em que praza a Deus proporcionar-lhes meios de se adiantarem. Se praticam o mal, é pelo despeito de ainda não poderem gozar do bem. 200 – Allan Kar dec', 'rascunho'),
  (585, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Que pensais da divisão da Natureza em três reinos, ou melhor, em duas classes: a dos seres orgânicos e a dos inorgânicos? Segundo alguns, a espécie humana forma uma quarta classe. Qual destas divisões é preferível?', 'Todas são boas, conforme o ponto de vista. Do ponto de vista material, apenas há seres orgânicos e inorgânicos. Do ponto de vista moral, há evidentemente quatro graus." Esses quatro graus apresentam, com efeito, caracteres determinados, muito embora pareçam confundir-se nos seus limites extremos. A matéria inerte, que constitui o reino mineral, só tem em si uma força mecânica. As plantas, ainda que compostas de matéria inerte, são dotadas de vitalidade. Os animais, também compostos de matéria inerte e igualmente dotados de vitalidade, possuem, além disso, uma espécie de inteligência instintiva, limitada, e a consciência de sua existência e de suas individualidades. O homem, tendo tudo o que há nas plantas e nos animais, domina todas as outras classes por uma inteligência especial, indefinida, que lhe dá a consciência do seu futuro, a percepção das coisas extramateriais e o conhecimento de Deus.', 'rascunho'),
  (586, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Têm as plantas consciência de que existem?', 'Não, pois que não pensam; só têm vida orgânica.', 'rascunho'),
  (587, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Experimentam sensações? Sofrem quando as mutilam?', 'Recebem impressões físicas que atuam sobre a matéria, mas não têm percepções. Conseguintemente, não têm a sensação da dor.', 'rascunho'),
  (588, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Independe da vontade delas a força que as atrai umas para as outras?', 'Certo, porquanto não pensam. É uma força mecânica da matéria, que atua sobre a matéria, sem que elas possam a isso opor-se.', 'rascunho'),
  (589, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Algumas plantas, como a sensitiva e a dionéia, por exemplo, executam movimentos que denotam grande sensibilidade e, em certos casos, uma espécie de vontade, conforme se observa na segunda, cujos lóbulos apanham a mosca que sobre ela pousa para sugá-la, parecendo que urde uma armadilha com o fim de capturar e matar aquele inseto. São dotadas essas plantas da faculdade de pensar? Têm vontade e formam uma classe intermediária entre a Natureza vegetal e a Natureza animal? Constituem a transição de uma para outra?', 'Tudo em a Natureza é transição, por isso mesmo que uma coisa não se assemelha a outra e, no entanto, todas se prendem umas às outras. As plantas não pensam; por conseguinte carecem de vontade. Nem a ostra que se abre, nem os zoófitos pensam: têm apenas um instinto cego e natural." O organismo humano nos proporciona exemplo de movimentos análogos, sem participação da vontade, nas funções digestivas e circulatórias. O piloro se contrai, ao contacto de certos corpos, para lhes negar passagem. O mesmo provavelmente se dá na sensitiva, cujos movimentos de nenhum modo implicam a necessidade de percepção e, ainda menos, da vontade.', 'rascunho'),
  (590, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Não haverá nas plantas, como nos animais, um instinto de conservação, que as induza a procurar o que lhes possa ser útil e a evitar o que lhes possa ser nocivo?', 'Há, se quiserdes, uma espécie de instinto, dependendo isso da extensão que se dê ao significado desta palavra. É, porém, um instinto puramente mecânico. Quando, nas operações químicas, observais que dois corpos se reúnem, é que um ao outro convém; quer dizer: é que há entre eles afinidade. Ora, a isto não dais o nome de instinto.', 'rascunho'),
  (591, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Nos mundos superiores, as plantas são de natureza mais perfeita, como os outros seres?', 'Tudo é mais perfeito. As plantas, porém, são sempre plantas, como os animais sempre animais e os homens sempre homens.', 'rascunho'),
  (592, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Se, pelo que toca à inteligência, comparamos o homem e os animais, parece difícil estabelecer-se uma linha de demarcação entre aquele e estes, porquanto alguns animais mostram, sob esse aspecto, notória superioridade sobre certos homens. Pode essa linha de demarcação ser estabelecida de modo preciso?', 'A este respeito é completo o desacordo entre os vossos filósofos. Querem uns que o homem seja um animal e outros que o animal seja um homem. Estão todos em erro. O homem é um ser à parte, que desce muito baixo algumas vezes e que pode também elevar-se muito alto. Pelo físico, é como os animais e menos bem- dotado do que muitos destes. A Natureza lhes deu tudo o que o homem é obrigado a inventar com a sua inteligência, para satisfação de suas necessidades e para sua conservação. Seu corpo se destrói, como o dos animais, é certo, mas ao seu Espírito está assinado um destino que só ele pode compreender, porque só ele é inteiramente livre. Pobres homens, que vos rebaixais mais do que os brutos! não sabeis distinguir- vos deles? Reconhecei o homem pela faculdade de pensar em Deus.', 'rascunho'),
  (593, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Poder-se-á dizer que os animais só obram por instinto? 202 – Allan Kar dec', 'Ainda aí há um sistema. É verdade que na maioria dos animais domina o instinto. Mas, não vês que muitos obram denotando acentuada vontade? É que têm inteligência, porém limitada." Não se poderia negar que, além de possuírem o instinto, alguns animais praticam atos combinados, que denunciam vontade de operar em determinado sentido e de acordo com as circunstâncias. Há, pois, neles, uma espécie de inteligência, mas cujo exercício quase que se circunscreve à utilização dos meios de satisfazerem às suas necessidades físicas e de proverem à conservação própria. Nada, porém, criam, nem melhora alguma realizam. Qualquer que seja a arte com que executem seus trabalhos, fazem hoje o que faziam outrora e o fazem, nem melhor, nem pior, segundo formas e proporções constantes e invariáveis. A cria, separada dos de sua espécie, não deixa por isso de construir o seu ninho de perfeita conformidade com os seus maiores, sem que tenha recebido nenhum ensino. O desenvolvimento intelectual de alguns, que se mostram suscetíveis de certa educação, desenvolvimento, aliás, que não pode ultrapassar acanhados limites, é devido à ação do homem sobre uma natureza maleável, porquanto não há aí progresso que lhe seja próprio. Mesmo o progresso que realizam pela ação do homem é efêmero e puramente individual, visto que, entregue a si mesmo, não tarda que o animal volte a encerrar-se nos limites que lhe traçou a Natureza.', 'rascunho'),
  (594, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Têm os animais alguma linguagem?', 'Se vos referis a uma linguagem formada de sílabas e palavras, não. Meio, porém, de se comunicarem entre si, têm. Dizem uns aos outros muito mais coisas do que imaginais. Mas, essa mesma linguagem de que dispõem é restrita às necessidades, como restritas também são as idéias que podem ter." a) — Há, entretanto, animais que carecem de voz. Esses parece que nenhuma linguagem usam, não? "Compreendem-se por outros meios. Para vos comunicardes reciprocamente, vós outros, homens, só dispondes da palavra? E os mudos? Facultada lhes sendo a vida de relação, os animais possuem meios de se prevenirem e de exprimirem as sensações que experimentam. Pensais que os peixes não se entendem entre si? O homem não goza do privilégio exclusivo da linguagem. Porém, a dos animais é instintiva e circunscrita pelas suas necessidades e idéias, ao passo que a do homem é perfectível e se presta a todas as concepções da sua inteligência." Efetivamente, os peixes que, como as andorinhas, emigram em cardumes, obedientes ao guia que os conduz, devem ter meios de se advertirem, de se entenderem e combinarem. É possível que disponham de uma vista mais penetrante e esta lhes permita perceber os sinais que mutuamente façam. Pode ser também que tenham na água um veículo próprio para a transmissão de certas vibrações. Como quer que seja, o que é incontestável é que lhes não falecem meios de se entenderem, do mesmo modo que a todos os animais carentes de voz e que, não obstante, trabalham em comum. Diante disso, que admiração pode causar que os Espíritos entre si se comuniquem sem o auxílio da palavra articulada?', 'rascunho'),
  (595, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Gozam de livre-arbítrio os animais, para a prática dos seus atos?', 'Os animais não são simples máquinas, como supondes. Contudo, a liberdade de ação, de que desfrutam, é limitada pelas suas necessidades e não se pode comparar à do homem. Sendo muitíssimo inferiores a este, não têm os mesmos deveres que ele. A liberdade, possuem-na restrita aos atos da vida material.', 'rascunho'),
  (596, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Donde procede a aptidão que certos animais denotam para imitar a linguagem do homem e por que essa aptidão se revela mais nas aves do que no macaco, por exemplo, cuja conformação apresenta mais analogia com a humana?', 'Origina-se de uma particular conformação dos órgãos vocais, reforçada pelo instinto de imitação. O macaco imita os gestos; algumas aves imitam a voz.', 'rascunho'),
  (597, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Pois que os animais possuem uma inteligência que lhes faculta certa liberdade de ação, haverá neles algum princípio independente da matéria?', 'Há e que sobrevive ao corpo." a) — Será esse princípio uma alma semelhante à do homem? "É também uma alma, se quiserdes, dependendo isto do sentido que se der a esta palavra. É, porém, inferior à do homem. Há entre a alma dos animais e a do homem distância equivalente à que medeia entre a alma do homem e Deus.', 'rascunho'),
  (598, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Após a morte, conserva a alma dos animais a sua individualidade e a consciência de si mesma?', 'Conserva sua individualidade; quanto à consciência do seu eu, não. A vida inteligente lhe permanece em estado latente.', 'rascunho'),
  (599, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'À alma dos animais é dado escolher a espécie de animal em que encarne?', 'Não, pois que lhe falta livre-arbítrio.', 'rascunho'),
  (600, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Sobrevivendo ao corpo em que habitou, a alma do animal vem a achar-se, depois da morte, num estado de erraticidade, como a do homem?', 'Fica numa espécie de erraticidade, pois que não mais se acha unida ao corpo, mas não é um Espírito errante. O Espírito errante é um ser que pensa e obra por sua livre vontade. De idêntica faculdade não dispõe o dos animais. A consciência de si mesmo é o que constitui o principal atributo do Espírito. O do animal, depois da morte, é classificado pelos Espíritos a quem incumbe essa tarefa e utilizado quase imediatamente. Não lhe é dado tempo de entrar em relação com outras criaturas.', 'rascunho'),
  (601, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Os animais estão sujeitos, como o homem, a uma lei progressiva?', 'Sim; e daí vem que nos mundos superiores, onde os homens são mais adiantados, os animais também o são, dispondo de meios mais amplos de comunicação. São sempre, porém, inferiores ao homem e se lhe acham submetidos, tendo neles o homem servidores inteligentes." Nada há nisso de extraordinário. Tomemos os nossos mais inteligentes animais, o cão, o elefante, o cavalo, e imaginemo-los dotados de uma conformação apropriada a trabalhos manuais. Que não fariam sob a direção do homem?', 'rascunho'),
  (602, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Os animais progridem, como o homem, por ato da própria vontade, ou pela força das coisas? 204 – Allan Kar dec', 'Pela força das coisas, razão por que não estão sujeitos à expiação.', 'rascunho'),
  (603, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Nos mundos superiores, os animais conhecem a Deus?', 'Não. Para eles o homem é um deus, como outrora os Espíritos eram deuses para o homem.', 'rascunho'),
  (604, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Pois que os animais, mesmo os aperfeiçoados, existentes nos mundos superiores, são sempre inferiores ao homem, segue-se que Deus criou seres intelectuais perpetuamente destinados à inferioridade, o que parece em desacordo com a unidade de vistas e de progresso que todas as suas obras revelam.', 'Tudo em a Natureza se encadeia por elos que ainda não podeis apreender. Assim, as coisas aparentemente mais díspares têm pontos de contacto que o homem, no seu estado atual, nunca chegará a compreender. Por um esforço da inteligência poderá entrevê-los; mas, somente quando essa inteligência estiver no máximo grau de desenvolvimento e liberta dos preconceitos do orgulho e da ignorância, logrará ver claro na obra de Deus. Até lá, suas muito restritas idéias lhe farão observar as coisas por um mesquinho e acanhado prisma. Sabei não ser possível que Deus se contradiga e que, na Natureza, tudo se harmoniza mediante leis gerais, que por nenhum de seus pontos deixam de corresponder à sublime sabedoria do Criador." a) — A inteligência é então uma propriedade comum, um ponto de contacto entre a alma dos animais e a do homem? "É, porém os animais só possuem a inteligência da vida material. No homem, a inteligência proporciona a vida moral.', 'rascunho'),
  (605, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Considerando-se todos os pontos de contacto que existem entre o homem e os animais, não seria lícito pensar que o homem possui duas almas: a alma animal e a alma espírita e que, se esta última não existisse, só como o bruto poderia ele viver? Por outra: que o animal é um ser semelhante ao homem, tendo de menos a alma espírita? Dessa maneira de ver resultaria serem os bons e os maus instintos do homem efeito da predominância de uma ou outra dessas almas?', 'Não, o homem não tem duas almas. O corpo, porém, tem seus instintos, resultantes da sensação peculiar aos órgãos. Dupla, no homem, só é a natureza. Há nele a natureza animal e a natureza espiritual. Participa, pelo seu corpo, da natureza dos animais e de seus instintos. Por sua alma, participa da dos Espíritos." a) — De modo que, além de suas próprias imperfeições de que cumpre ao Espírito despojar-se, tem ainda o homem que lutar contra a influência da matéria? "Quanto mais inferior é o Espírito, tanto mais apertados são os laços que o ligam à matéria. Não o vedes? O homem não tem duas almas; a alma é sempre única em cada ser. São distintas uma da outra a alma do animal e a do homem, a tal ponto que a de um não pode animar o corpo criado para o outro. Mas, conquanto não tenha alma animal, que, por suas paixões, o nivele aos animais, o homem tem o corpo que, às vezes, o rebaixa até ao nível deles, por isso que o corpo é um ser dotado de vitalidade e de instintos, porém ininteligentes estes e restritos ao cuidado que a sua conservação requer." Encarnando no corpo do homem, o Espírito lhe traz o princípio intelectual e moral, que o torna superior aos animais. As duas naturezas nele existentes dão às suas paixões duas origens diferentes: umas provêm dos instintos da natureza animal, provindo as outras das impurezas do Espírito, de cuja encarnação é ele a imagem e que mais ou menos simpatiza com a grosseria dos apetites animais. Purificando-se, o Espírito se liberta pouco a pouco da influência da matéria. Sob essa influência, aproxima-se do bruto. Isento dela, eleva-se à sua verdadeira destinação.', 'rascunho'),
  (606, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Donde tiram os animais o princípio inteligente que constitui a alma de natureza especial de que são dotados?', 'Do elemento inteligente universal." a) — Então, emanam de um único princípio a inteligência do homem e a dos animais? "Sem dúvida alguma, porém, no homem, passou por uma elaboração que a coloca acima da que existe no animal.', 'rascunho'),
  (607, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Dissestes que o estado da alma do homem, na sua origem, corresponde ao estado da infância na vida corporal, que sua inteligência apenas desabrocha e se ensaia para a vida. Onde passa o Espírito essa primeira fase do seu desenvolvimento?', 'Numa série de existências que precedem o período a que chamais Humanidade." a) — Parece que, assim, se pode considerar a alma como tendo sido o princípio inteligente dos seres inferiores da criação, não? "Já não dissemos que tudo em a Natureza se encadeia e tende para a unidade? Nesses seres, cuja totalidade estais longe de conhecer, é que o princípio inteligente se elabora, se individualiza pouco a pouco e se ensaia para a vida, conforme acabamos de dizer. É, de certo modo, um trabalho preparatório, como o da germinação, por efeito do qual o princípio inteligente sofre uma transformação e se torna Espírito. Entra então no período da humanização, começando a ter consciência do seu futuro, capacidade de distinguir o bem do mal e a responsabilidade dos seus atos. Assim, à fase da infância se segue a da adolescência, vindo depois a da juventude e da madureza. Nessa origem, coisa alguma há de humilhante para o homem. Sentir-se-ão humilhados os grandes gênios por terem sido fetos informes nas entranhas que os geraram? Se alguma coisa há que lhe seja humilhante, é a sua inferioridade perante Deus e sua impotência para lhe sondar a profundeza dos desígnios e para apreciar a sabedoria das leis que regem a harmonia do Universo. Reconhecei a grandeza de Deus nessa admirável harmonia, mediante a qual tudo é solidário na Natureza. Acreditar que Deus haja feito, seja o que for, sem um fim, e criado seres inteligentes sem futuro, fora blasfemar da sua bondade, que se estende por sobre todas as suas criaturas." b) — Esse período de humanização principia na Terra? "A Terra não é o ponto de partida da primeira encarnação humana. O período da humanização começa, geralmente, em mundos ainda inferiores à Terra. 206 – Allan Kar dec Isto, entretanto, não constitui regra absoluta, pois pode suceder que um Espírito, desde o seu início humano, esteja apto a viver na Terra. Não é freqüente o caso; constitui antes uma exceção.', 'rascunho'),
  (608, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'O Espírito do homem tem, após a morte, consciência de suas existências anteriores ao período de humanidade?', 'Não, pois não é desse período que começa a sua vida de Espírito. Difícil é mesmo que se lembre de suas primeiras existências humanas, como difícil é que o homem se lembre dos primeiros tempos de sua infância e ainda menos do tempo que passou no seio materno. Essa a razão por que os Espíritos dizem que não sabem como começaram.', 'rascunho'),
  (609, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Uma vez no período da humanidade, conserva o Espírito traços do que era precedentemente, quer dizer: do estado em que se achava no período a que se poderia chamar ante-humano?', 'Conforme a distância que medeie entre os dois períodos e o progresso realizado. Durante algumas gerações, pode ele conservar vestígios mais ou menos pronunciados do estado primitivo, porquanto nada se opera na Natureza por brusca transição. Há sempre anéis que ligam as extremidades da cadeia dos seres e dos acontecimentos. Aqueles vestígios, porém, se apagam com o desenvolvimento do livre-arbítrio. Os primeiros progressos só muito lentamente se efetuam, porque ainda não têm a secundá-los a vontade. Vão em progressão mais rápida, à medida que o Espírito adquire mais perfeita consciência de si mesmo.', 'rascunho'),
  (610, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Ter-se-ão enganado os Espíritos que disseram constituir o homem um ser à parte na ordem da criação?', 'Não, mas a questão não fora desenvolvida. Demais, há coisas que só a seu tempo podem ser esclarecidas. O homem é, com efeito, um ser à parte, visto possuir faculdades que o distinguem de todos os outros e ter outro destino. A espécie humana é a que Deus escolheu para a encarnação dos seres que podem conhecê-lo.', 'rascunho'),
  (611, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'O terem os seres vivos uma origem comum no princípio inteligente não é a consagração da doutrina da metempsicose?', 'Duas coisas podem ter a mesma origem e absolutamente não se assemelharem mais tarde. Quem reconheceria a árvore, com suas folhas, flores e frutos, no gérmen informe que se contém na semente donde ela surge? Desde que o princípio inteligente atinge o grau necessário para ser Espírito e entrar no período da humanização, já não guarda relação com o seu estado primitivo e já não é a alma dos animais, como a árvore já não é a semente. De animal só há no homem o corpo e as paixões que nascem da influência do corpo e do instinto de conservação inerente à matéria. Não se pode, pois, dizer que tal homem é a encarnação do Espírito de tal animal. Conseguintemente, a metempsicose, como a entendem, não é verdadeira.', 'rascunho'),
  (612, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Poderia encarnar num animal o Espírito que animou o corpo de um homem?', 'Isso seria retrogradar e o Espírito não retrograda. O rio não remonta à sua nascente.', 'rascunho'),
  (613, 'Parte Segunda — Do mundo espírita ou mundo dos Espíritos', 'Capítulo XI — Dos três reinos', 'Embora de todo errônea, a idéia ligada à metempsicose não terá resultado do sentimento intuitivo que o homem possui de suas diferentes existências?', 'Nessa, como em muitas outras crenças, se depara esse sentimento intuitivo. O homem, porém, o desnaturou, como costuma fazer com a maioria de suas idéias intuitivas." Seria verdadeira a metempsicose, se indicasse a progressão da alma, passando de um estado inferior a outro superior, onde adquirisse desenvolvimentos que lhe transformassem a natureza. É, porém, falsa no sentido de transmigração direta da alma do animal para o homem e reciprocamente, o que implicaria a idéia de uma retrogradação, ou de fusão. Ora, o fato de não poder semelhante fusão operar-se, entre os seres corporais das duas espécies, mostra que estas são de graus inassimiláveis, devendo dar-se o mesmo com relação aos Espíritos que as animam. Se um mesmo Espírito as pudesse animar alternativamente, haveria, como conseqüência, uma identidade de natureza, traduzindo-se pela possibilidade da reprodução material. A reencarnação, como os Espíritos a ensinam, se funda, ao contrário, na marcha ascendente da Natureza e na progressão do homem, dentro da sua própria espécie, o que em nada lhe diminui a dignidade. O que o rebaixa é o mau uso que ele faz das faculdades que Deus lhe outorgou para que progrida. Seja como for, a ancianidade e a universalidade da doutrina da metempsicose e, bem assim, a circunstância de a terem professado homens eminentes provam que o princípio da reencarnação se radica na própria Natureza. Antes, pois, constituem argumentos a seu favor, que contrários a esse princípio. O ponto inicial do Espírito é uma dessas questões que se prendem à origem das coisas e de que Deus guarda o segredo. Dado não é ao homem conhecê-las de modo absoluto, nada mais lhe sendo possível a tal respeito do que fazer suposições, criar sistemas mais ou menos prováveis. Os próprios Espíritos longe estão de tudo saberem e, acerca do que não sabem, também podem ter opiniões pessoais mais ou menos sensatas. É assim, por exemplo, que nem todos pensam da mesma forma quanto às relações existentes entre o homem e os animais. Segundo uns, o Espírito não chega ao período humano senão depois de se haver elaborado e individualizado nos diversos graus dos seres inferiores da Criação. Segundo outros, o Espírito do homem teria pertencido sempre à raça humana, sem passar pela fieira animal. O primeiro desses sistemas apresenta a vantagem de assinar um alvo ao futuro dos animais, que formariam então os primeiros elos da cadeia dos seres pensantes. O segundo é mais conforme à dignidade do homem e pode resumir-se da maneira seguinte: As diferentes espécies de animais não procedem intelectualmente umas das outras, mediante progressão. Assim, o espírito da ostra não se torna sucessivamente o do peixe, do pássaro, do quadrúpede e do quadrúmano. Cada espécie constitui, física e moralmente, um tipo absoluto, cada um de cujos indivíduos haure na fonte universal a quantidade do princípio inteligente que lhe seja necessário, de acordo com a perfeição de seus órgãos e com o trabalho que tenha de executar nos fenômenos da Natureza, quantidade que ele, por sua morte, restitui ao reservatório donde a tirou. Os dos mundos mais adiantados que o nosso (ver nº 188) constituem igualmente raças distintas, apropriadas às necessidades desses mundos e ao grau de adiantamento dos homens, cujos auxiliares eles são, mas de modo nenhum procedem das da Terra, espiritualmente falando. Outro tanto não se dá com o homem. Do ponto de vista físico, este forma evidentemente um elo da cadeia dos seres vivos; porém, do ponto de vista moral, há, entre o animal e o homem, solução de continuidade. O homem possui, como 208 – Allan Kar dec propriedade sua, a alma ou Espírito, centelha divina que lhe confere o senso moral e um alcance intelectual de que carecem os animais e que é nele o ser principal, que preexiste e sobrevive ao corpo, conservando sua individualidade. Qual a origem do Espírito? Onde o seu ponto inicial? Forma-se do princípio inteligente individualizado? Tudo isso são mistérios que fora inútil querer devassar e sobre os quais, como dissemos, nada mais se pode fazer do que construir sistemas. O que é constante, o que ressalta do raciocínio e da experiência é a sobrevivência do Espírito, a conservação de sua individualidade após a morte, a progressividade de suas faculdades, seu estado feliz ou desgraçado de acordo com o seu adiantamento na senda do bem e todas as verdades morais decorrentes deste princípio. Quanto às relações misteriosas que existem entre o homem e os animais, isso, repetimos, está nos segredos de Deus, como muitas outras coisas, cujo conhecimento atual nada importa ao nosso progresso e sobre as quais seria inútil determo-nos.', 'rascunho'),
  (614, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Que se deve entender por lei natural?', 'A lei natural é a lei de Deus. É a única verdadeira para a felicidade do homem. Indica-lhe o que deve fazer ou deixar de fazer e ele só é infeliz quando dela se afasta.', 'rascunho'),
  (615, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'É eterna a lei de Deus?', 'Eterna e imutável como o próprio Deus.', 'rascunho'),
  (616, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Será possível que Deus em certa época haja prescrito aos homens o que noutra época lhes proibiu?', 'Deus não se engana. Os homens é que são obrigados a modificar suas leis, por imperfeitas. As de Deus, essas são perfeitas. A harmonia que reina no universo material, como no universo moral, se funda em leis estabelecidas por Deus desde toda a eternidade.', 'rascunho'),
  (617, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'As leis divinas, que é o que compreendem no seu âmbito? Concernem a alguma outra coisa, que não somente ao procedimento moral?', 'Todas as da Natureza são leis divinas, pois que Deus é o autor de tudo. O sábio estuda as leis da matéria, o homem de bem estuda e pratica as da alma." a) — Dado é ao homem aprofundar umas e outras? "É, mas uma única existência não lhe basta para isso." Efetivamente, que são alguns anos para a aquisição de tudo o de que precisa o ser, a fim de se considerar perfeito, embora apenas se tenha em conta a distancia que vai do selvagem ao homem civilizado? Insuficiente seria, para tanto, a existência mais longa que se possa imaginar. Ainda com mais forte razão o será quando curta, como é para a maior parte dos homens. Entre as leis divinas, umas regulam o movimento e as relações da matéria bruta: as leis físicas, cujo estudo pertence ao domínio da Ciência. As outras dizem respeito especialmente ao homem considerado em si mesmo e nas suas relações com Deus e com seus semelhantes. Contêm as regras da vida do corpo, bem como as da vida da alma: são as leis morais.', 'rascunho'),
  (618, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'São as mesmas, para todos os mundos, as leis divinas?', 'A razão está a dizer que devem ser apropriadas à natureza de cada mundo e adequadas ao grau de progresso dos seres que os habitam.', 'rascunho'),
  (619, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'A todos os homens facultou Deus os meios de conhecerem sua lei?', 'Todos podem conhecê-la, mas nem todos a compreendem. Os homens de bem e os que se decidem a investigá-la são os que melhor a compreendem. Todos, entretanto, a compreenderão um dia, porquanto forçoso é que o progresso se efetue." A justiça das diversas encarnações do homem é uma conseqüência deste princípio, pois que, em cada nova existência, sua inteligência se acha mais desenvolvida e ele compreende melhor o que é bem e o que é mal. Se numa só existência tudo lhe devesse ficar ultimado, qual seria a sorte de tantos milhões de seres que morrem todos os dias no embrutecimento da selvageria, ou nas trevas da ignorância, sem que deles tenha dependido o se instruírem? (171-222)', 'rascunho'),
  (620, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Antes de se unir ao corpo, a alma compreende melhor a lei de Deus do que depois de encarnada?', 'Compreende-a de acordo com o grau de perfeição que tenha atingido e dela guarda a intuição quando unida ao corpo. Os maus instintos, porém, fazem ordinariamente que o homem a esqueça.', 'rascunho'),
  (621, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Onde está escrita a lei de Deus?', 'Na consciência." a) — Visto que o homem traz em sua consciência a lei de Deus, que necessidade havia de lhe ser ela revelada? "Ele a esquecera e desprezara. Quis então Deus lhe fosse lembrada.', 'rascunho'),
  (622, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Confiou Deus a certos homens a missão de revelarem a sua lei?', 'Indubitavelmente. Em todos os tempos houve homens que tiveram essa missão. São Espíritos superiores, que encarnam com o fim de fazer progredir a Humanidade.', 'rascunho'),
  (623, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Os que hão pretendido instruir os homens na lei de Deus não se têm enganado algumas vezes, fazendo-os transviar-se por meio de falsos princípios?', 'Certamente hão dado causa a que os homens se transviassem aqueles que não eram inspirados por Deus e que, por ambição, tomaram sobre si um encargo que 212 – Allan Kar dec lhes não fora cometido. Todavia, como eram, afinal, homens de gênio, mesmo entre os erros que ensinaram, grandes verdades muitas vezes se encontram.', 'rascunho'),
  (624, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Qual o caráter do verdadeiro profeta?', 'O verdadeiro profeta é um homem de bem, inspirado por Deus. Podeis reconhecê-lo pelas suas palavras e pelos seus atos. Impossível é que Deus se sirva da boca do mentiroso para ensinar a verdade.', 'rascunho'),
  (625, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Qual o tipo mais perfeito que Deus tem oferecido ao homem, para lhe servir de guia e modelo?', 'Jesus." Para o homem, Jesus constitui o tipo da perfeição moral a que a Humanidade pode aspirar na Terra. Deus no-lo oferece como o mais perfeito modelo e a doutrina que ensinou é a expressão mais pura da lei do Senhor, porque, sendo ele o mais puro de quantos têm aparecido na Terra, o Espírito Divino o animava. Quanto aos que, pretendendo instruir o homem na lei de Deus, o têm transviado, ensinando-lhe falsos princípios, isso aconteceu por haverem deixado que os dominassem sentimentos demasiado terrenos e por terem confundido as leis que regulam as condições da vida da alma, com as que regem a vida do corpo. Muitos hão apresentado como leis divinas simples leis humanas estatuídas para servir às paixões e dominar os homens.', 'rascunho'),
  (626, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Só por Jesus foram reveladas as leis divinas e naturais? Antes do seu aparecimento, o conhecimento dessas leis só por intuição os homens o tiveram?', 'Já não dissemos que elas estão escritas por toda parte? Desde os séculos mais longínquos, todos os que meditaram sobre a sabedoria hão podido compreendê- las e ensiná-las. Pelos ensinos, mesmo incompletos, que espalharam, prepararam o terreno para receber a semente. Estando as leis divinas escritas no livro da natureza, possível foi ao homem conhecê-las, logo que as quis procurar. Por isso é que os preceitos que consagram foram, desde todos os tempos, proclamados pelos homens de bem; e também por isso é que elementos delas se encontram, se bem que incompletos ou adulterados pela ignorância, na doutrina moral de todos os povos saídos da barbárie.', 'rascunho'),
  (627, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Uma vez que Jesus ensinou as verdadeiras leis de Deus, qual a utilidade do ensino que os Espíritos dão? Terão que nos ensinar mais alguma coisa?', 'Jesus empregava amiúde, na sua linguagem, alegorias e parábolas, porque falava de conformidade com os tempos e os lugares. Faz-se mister agora que a verdade se torne inteligível para todo mundo. Muito necessário é que aquelas leis sejam explicadas e desenvolvidas, tão poucos são os que as compreendem e ainda menos os que as praticam. A nossa missão consiste em abrir os olhos e os ouvidos a todos, confundindo os orgulhosos e desmascarando os hipócritas: os que vestem a capa da virtude e da religião, a fim de ocultarem suas torpezas. O ensino dos Espíritos tem que ser claro e sem equívocos, para que ninguém possa pretextar ignorância e para que todos o possam julgar e apreciar com a razão. Estamos incumbidos de preparar o reino do bem que Jesus anunciou. Daí a necessidade de que a ninguém seja possível interpretar a lei de Deus ao sabor de suas paixões, nem falsear o sentido de uma lei toda de amor e de caridade.', 'rascunho'),
  (628, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Por que a verdade não foi sempre posta ao alcance de toda gente?', 'Importa que cada coisa venha a seu tempo. A verdade é como a luz: o homem precisa habituar-se a ela, pouco a pouco; do contrário, fica deslumbrado." "Jamais permitiu Deus que o homem recebesse comunicações tão completas e instrutivas como as que hoje lhe são dadas. Havia, como sabeis, na antiguidade alguns indivíduos possuidores do que eles próprios consideravam uma ciência sagrada e da qual faziam mistério para os que, aos seus olhos, eram tidos por profanos. Pelo que conheceis das leis que regem estes fenômenos, deveis compreender que esses indivíduos apenas recebiam algumas verdades esparsas, dentro de um conjunto equívoco e, na maioria dos casos, emblemático. Entretanto, para o estudioso, não há nenhum sistema antigo de filosofia, nenhuma tradição, nenhuma religião, que seja desprezível, pois em tudo há germens de grandes verdades que, se bem pareçam contraditórias entre si, dispersas que se acham em meio de acessórios sem fundamento, facilmente coordenáveis se vos apresentam, graças à explicação que o Espiritismo dá de uma imensidade de coisas que até agora se vos afiguraram sem razão alguma e cuja realidade está hoje irrecusavelmente demonstrada. Não desprezeis, portanto, os objetos de estudo que esses materiais oferecem. Ricos eles são de tais objetos e podem contribuir grandemente para vossa instrução.', 'rascunho'),
  (629, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Que definição se pode dar da moral?', 'A moral é a regra de bem proceder, isto é, de distinguir o bem do mal. Funda-se na observância da lei de Deus. O homem procede bem quando tudo faz pelo bem de todos, porque então cumpre a lei de Deus.', 'rascunho'),
  (630, 'Parte Terceira — Das leis morais', 'Capítulo I — Da lei divina ou natural', 'Como se pode distinguir o bem do mal?', 'O bem é tudo o que é conforme à lei de Deus; o mal, tudo o que lhe é contrário. Assim, fazer o bem é proceder de acordo com a lei de Deus. Fazer o mal é infringi-la.', 'rascunho')
